"""Edit vocabulary for the home_basketball_door scene.

Two bodies can be edited, and both of them are the point of the clip:

* **the ball** -- ``mass`` and ``speed`` decide how much momentum arrives at
  the leaf, which decides how far the door swings;
* **the door** -- ``mass`` decides how much of that momentum turns into
  rotation, and ``friction`` (a Coulomb resisting torque in the hinge, N m)
  decides how much of the rotation survives.

A viscous model would leave the swing angle independent of the leaf's inertia
(the inertia cancels between the impulse that starts the swing and the decay
that ends it), which is why this scene brakes with a constant torque instead.
With a constant torque the leaf stops after ``I w^2 / (2 tau)`` radians, and
``w`` itself goes as ``1/I``, so the swing scales as ``1/I``: three times the
leaf mass measured 32.73 -> 12.22 deg of travel (ratio 2.68, ideal 3), and four
times the hinge friction measured 32.73 -> 8.34 deg (ratio 3.92, ideal 4).

That scaling only reads on screen while the leaf has room to stop *before* the
jamb. With a slack hinge it reaches 0 deg every time and every edit looks the
same -- measured at tau = 0.45 N m, all six candidate cases travelled 43-45 deg.
The baseline therefore brakes at 4.0 N m and settles 12.3 deg ajar.

The baseline is read from ``scenario.json`` rather than copied here, so the
DSL, the prompts and the physics diffs cannot drift away from the scene.
"""

from __future__ import annotations

# Locate reference common scripts and install this scene's embedded helpers.
import sys as _bundle_sys0
from pathlib import Path as _BundlePath0
_BUNDLE_SCENE = _BundlePath0(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_PCVE_PROJECT_ROOT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys0.path:
    _bundle_sys0.path.insert(0, str(_BUNDLE_SCRIPTS))

# Scene-local source bundle: installed before importing scene support modules.
import importlib.abc as _bundle_abc
import importlib.util as _bundle_util
import json as _bundle_json
import sys as _bundle_sys
from pathlib import Path as _BundlePath

_BUNDLE_SCENE = _BundlePath(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_BUNDLE_PROJECT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys.path:
    _bundle_sys.path.insert(0, str(_BUNDLE_SCRIPTS))

_BUNDLE_SOURCES = _bundle_json.loads(r"""{"pcve_project_paths": "\"\"\"Path helpers shared by standalone rigid-scene folders.\"\"\"\nfrom pathlib import Path\nimport sys\n\n\ndef project_root(anchor):\n    anchor = Path(anchor).resolve()\n    candidates = (anchor, *anchor.parents)\n    for candidate in candidates:\n        if (candidate / \"assets\").is_dir() and (candidate / \"clean_scripts\").is_dir():\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate project root above {anchor}; expected assets/ and clean_scripts/\")\n\n\ndef scene_root(anchor):\n    \"\"\"Find the scene folder from argv first, then from the helper's parents.\"\"\"\n    candidates = []\n    if sys.argv and sys.argv[0] not in {\"-\", \"\"}:\n        argv_path = Path(sys.argv[0]).expanduser()\n        if not argv_path.is_absolute():\n            argv_path = Path.cwd() / argv_path\n        candidates.append(argv_path.resolve().parent)\n    anchor = Path(anchor).resolve()\n    candidates.extend(anchor.parents)\n    seen = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        if any(candidate.glob(\"simulate_*.py\")) and any(candidate.glob(\"render_*.py\")):\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate scene entrypoints above {anchor}\")\n", "pcve_scene_runtime": "\"\"\"Shared command-line and output contracts for PCVE scene entry points.\n\nBoth ``blender -b --python render.py -- ...`` and Python with bpy are supported.\nThis module has no Blender dependency until a renderer finishes.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport shutil\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n_render_args = None\n\n\ndef python_for(role: str) -> Path:\n    override = os.environ.get(\"PCVE_PHYSICS_PYTHON\" if role == \"physics\" else \"PCVE_RENDER_PYTHON\")\n    if override:\n        return Path(override).expanduser()\n    names = (\"sim/python.exe\", \"sim/bin/python\") if role == \"physics\" else (\n        \"render/Scripts/python.exe\", \"render/bin/python\")\n    for base in (ROOT / \".runtime\", ROOT.parent / \"PCVE-ElasticBench/.runtime\"):\n        for name in names:\n            if (base / name).is_file():\n                return base / name\n    if role == \"physics\":\n        # The original Linux setup activates a PyBullet conda environment and\n        # invokes Blender separately. Blender's sys.executable is not Python.\n        candidates = [ROOT.parent / \"miniconda/envs/physics/bin/python\"]\n        if os.environ.get(\"CONDA_PREFIX\"):\n            prefix = Path(os.environ[\"CONDA_PREFIX\"])\n            candidates += [prefix / \"python.exe\", prefix / \"bin/python\"]\n        for name in (\"python3\", \"python\"):\n            if shutil.which(name):\n                candidates.append(Path(shutil.which(name)))\n        for candidate in candidates:\n            if candidate.is_file() and \"blender\" not in candidate.name.lower():\n                return candidate\n    return Path(sys.executable)\n\n\ndef _add(parser, flag, **kwargs):\n    if flag not in parser._option_string_actions:\n        parser.add_argument(flag, **kwargs)\n\n\ndef implementation_hashes(directory):\n    files = list(Path(directory).glob(\"*.py\"))\n    files += [ROOT / \"clean_scripts\" / name for name in (\"pcve_scene_pipeline.py\", \"pcve_edit_dsl.py\")]\n    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in files if path.is_file()}\n\n\ndef case_outputs(folder):\n    \"\"\"Semantic output keys used by the original suite manifests.\"\"\"\n    names = dict(video=\"video.mp4\", ground_truth=\"ground_truth_transforms.json\",\n                 scenario_metadata=\"scenario_metadata.json\", scenario_overrides=\"scenario_overrides.json\",\n                 physics=\"physics_transforms.json\", scenario_input=\"scenario_input.json\", preview=\"preview.png\")\n    return {key: str((Path(folder) / name).resolve()) for key, name in names.items()\n            if (Path(folder) / name).is_file()}\n\n\ndef add_build_arguments(parser):\n    _add(parser, \"--blender\", type=Path, help=\"Blender executable; otherwise use render Python with bpy.\")\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    _add(parser, \"--render-python\", type=Path, default=python_for(\"render\"))\n    _add(parser, \"--engine\", choices=(\"cycles\", \"eevee\"), default=\"cycles\")\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    return parser\n\n\ndef render_prefix(args, script: Path) -> list[str]:\n    blender = getattr(args, \"blender\", None) or os.environ.get(\"BLENDER_BIN\")\n    render_python = Path(getattr(args, \"render_python\", python_for(\"render\")))\n    if not blender and render_python == Path(sys.executable):\n        candidates = [ROOT / \"tools/blender-3.6.23-linux-x64/blender\"]\n        if shutil.which(\"blender\"):\n            candidates.append(Path(shutil.which(\"blender\")))\n        blender = next((path for path in candidates if path.is_file()), None)\n    if blender:\n        # Blender otherwise returns success even when the Python script raises.\n        return [str(Path(blender).expanduser()), \"-b\", \"--python-exit-code\", \"1\",\n                \"--python\", str(script), \"--\"]\n    return [str(render_python), str(script)]\n\n\ndef append_render_options(command, args):\n    for name in (\"engine\", \"device\", \"preview_frame\"):\n        flag = \"--\" + name.replace(\"_\", \"-\")\n        value = getattr(args, name, None)\n        if value is not None and flag not in command:\n            command += [flag, str(value)]\n    return command\n\n\ndef parse_render_args(parser, argv=None):\n    global _render_args\n    _add(parser, \"--seed\", type=int, default=0)\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    # Renderers without an engine switch currently implement Cycles only.\n    _add(parser, \"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    if argv is None:\n        argv = sys.argv[sys.argv.index(\"--\") + 1:] if \"--\" in sys.argv else sys.argv[1:]\n    _render_args = parser.parse_args(argv)\n    # In the original CLI duration-sec is the real-time clip length. A scene's\n    # optional demo slow-motion preset must not silently multiply that request.\n    if \"--duration-sec\" in argv and \"--slow-motion\" not in argv and hasattr(_render_args, \"slow_motion\"):\n        _render_args.slow_motion = 1\n    random.seed(_render_args.seed)\n    return _render_args\n\n\ndef apply_physics_overrides(args, baseline):\n    \"\"\"Read the original {physics: ...} override format for scalar CLI scenes.\n\n    Bare schedule arrays remain accepted by the older timed-edit escape hatch.\n    Explicit scalar command-line values take precedence over the JSON defaults.\n    \"\"\"\n    path = getattr(args, \"scenario_overrides_json\", None)\n    if path is None:\n        return None\n    payload = json.loads(Path(path).read_text(encoding=\"utf-8\"))\n    if isinstance(payload, list):\n        return Path(path)\n    physics = payload.get(\"physics\", payload)\n    unknown = set(physics) - {*baseline, \"timed_edits\"}\n    if unknown:\n        raise ValueError(f\"Unknown physics overrides: {sorted(unknown)}\")\n    for name, value in physics.items():\n        if name != \"timed_edits\" and getattr(args, name, None) is None:\n            setattr(args, name, value)\n    if physics.get(\"timed_edits\"):\n        target = Path(args.out_dir) / \"timed_edits.json\"\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_text(json.dumps(physics[\"timed_edits\"], indent=2), encoding=\"utf-8\")\n        return target\n    return None\n\n\ndef _matrix(position, q):\n    x, y, z, w = q\n    return [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), position[0]],\n            [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), position[1]],\n            [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), position[2]],\n            [0, 0, 0, 1]]\n\n\ndef _optional_metrics(value):\n    if isinstance(value, dict):\n        return {key: _optional_metrics(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_optional_metrics(item) for item in value]\n    if isinstance(value, float) and not math.isfinite(value):\n        return None\n    return value\n\n\ndef finalize_render_outputs(out: Path, scene_name: str, args, scene=None):\n    \"\"\"Keep scene-specific files and also publish the original PCVE filenames.\"\"\"\n    out = Path(out).resolve()\n    gt_path = out / \"ground_truth_transforms.json\"\n    if gt_path.is_file():\n        gt = json.loads(gt_path.read_text(encoding=\"utf-8\"))\n        gt.setdefault(\"scene\", scene_name)\n        gt.setdefault(\"schema_version\", 1)\n        camera = gt.setdefault(\"camera\", {})\n        camera.setdefault(\"resolution\", list(args.resolution))\n        camera.setdefault(\"sensor_width_mm\", 36.0)\n        if scene is not None and scene.camera is not None:\n            cam = scene.camera\n            camera.update(matrix_world=[list(row) for row in cam.matrix_world],\n                          sensor_width_mm=float(cam.data.sensor_width),\n                          sensor_fit=cam.data.sensor_fit)\n            if cam.data.type == \"ORTHO\":\n                camera.update(projection=\"orthographic\", ortho_scale=float(cam.data.ortho_scale))\n            else:\n                camera.update(projection=\"perspective\", lens_mm=float(cam.data.lens))\n        frames = gt.get(\"frames\", [])\n        # toy_car_bottle retains its raw simulation and render_frames as well.\n        rendered = gt.get(\"render_frames\", [])\n        for index, frame in enumerate(frames):\n            frame.setdefault(\"frame_index\", frame.get(\"frame\", index + 1))\n            frame.setdefault(\"time_sec\", frame.get(\"time\", index / gt.get(\"fps\", 24)))\n            if camera.get(\"matrix_world\") is not None:\n                frame.setdefault(\"camera_matrix_world\", camera[\"matrix_world\"])\n            if index < len(rendered):\n                for name, state in rendered[index].get(\"objects\", {}).items():\n                    raw = frame.get(\"objects\", {}).get(name, {})\n                    frame[name] = dict(raw, present=True, location=state[\"position\"],\n                                       quaternion_xyzw=state[\"quaternion_xyzw\"],\n                                       matrix_world=_matrix(state[\"position\"], state[\"quaternion_xyzw\"]))\n        gt.setdefault(\"frame_start\", 1)\n        gt.setdefault(\"frame_end\", len(frames))\n        if scene_name == \"toy_car_bottle\":\n            layout = gt[\"config\"][\"layout\"]\n            gt[\"objects\"] = {\n                \"car\": {\"object_name\": \"toy_car\", \"dimensions\": [layout[\"car_length\"], layout[\"car_width\"], layout[\"car_height\"]]},\n                \"bottle\": {\"object_name\": \"plastic_bottle\", \"radius\": layout[\"bottle_radius\"], \"height\": layout[\"bottle_height\"]},\n            }\n        # A short diagnostic clip may not contain an impact. Its unavailable\n        # post-contact quality measurements are null; poses must stay finite.\n        for container in (gt, gt.get(\"physics\", {})):\n            if \"quality\" in container:\n                container[\"quality\"] = _optional_metrics(container[\"quality\"])\n        for frame in frames:\n            matrices = [item[\"matrix_world\"] for item in frame.values()\n                        if isinstance(item, dict) and \"matrix_world\" in item\n                        and not (item.get(\"present\") is False and item[\"matrix_world\"] is None)]\n            matrices += [item for key, item in frame.items() if key.endswith(\"_matrix_world\")]\n            for matrix in matrices:\n                if matrix is None:\n                    raise ValueError(\"A present object must have a ground-truth transform\")\n                if not all(math.isfinite(value) for row in matrix for value in row):\n                    raise ValueError(\"Non-finite ground-truth transform\")\n        gt_path.write_text(json.dumps(gt, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n    mode = getattr(args, \"mode\", \"preview\")\n    if mode == \"animation\":\n        stem = \"basketball_door\" if scene_name == \"home_basketball_door\" else scene_name\n        source = out / (stem + \".mp4\")\n        target = out / \"video.mp4\"\n        if source.is_file() and not (scene_name == \"uneven_ground_ball\" and getattr(args, \"label\", False)):\n            shutil.copy2(source, target)\n        if not target.is_file():\n            raise FileNotFoundError(f\"Animation did not produce {target}\")\n    refresh_alias = scene_name in (\"home_basketball_door\", \"pot_lid_drop\") or (\n        scene_name == \"toy_car_bottle\" and getattr(args, \"preview_frame\", None) is None)\n    if mode == \"preview\" and (refresh_alias or not (out / \"preview.png\").is_file()):\n        number = getattr(args, \"preview_frame\", None) or 1\n        candidates = [out / f\"preview_frame_{number:04d}.png\", out / \"first_frame.png\"]\n        candidates += sorted(out.glob(\"preview_frame_*.png\"))\n        source = next((p for p in candidates if p.is_file()), None)\n        if source is None:\n            raise FileNotFoundError(f\"Preview did not produce an image in {out}\")\n        shutil.copy2(source, out / \"preview.png\")\n\n\ndef run_renderer(main, scene_name):\n    global _render_args\n    _render_args = None\n    main()\n    if _render_args is not None:\n        import bpy\n        finalize_render_outputs(_render_args.out_dir, scene_name, _render_args, bpy.context.scene)\n", "pcve_blender_compat": "\"\"\"Small Blender 3.6/4.x API differences used by the scene renderers.\"\"\"\n\nSOCKET_NAMES = {\n    \"Coat Weight\": \"Clearcoat\", \"Coat Roughness\": \"Clearcoat Roughness\",\n    \"Specular IOR Level\": \"Specular\", \"Transmission Weight\": \"Transmission\",\n    \"Emission Color\": \"Emission\", \"Sheen Weight\": \"Sheen\",\n    \"Sheen Roughness\": \"Roughness\", \"Subsurface Weight\": \"Subsurface\",\n}\n\n\ndef shader_socket(node, name):\n    socket = node.inputs.get(name)\n    if socket is None:\n        socket = node.inputs.get(SOCKET_NAMES.get(name, name))\n    if socket is None:\n        raise KeyError(f\"{node.name}: missing shader input {name}\")\n    return socket\n\n\ndef set_shader_input(node, name, value):\n    socket = shader_socket(node, name)\n    if socket.type == \"VALUE\" and isinstance(value, (tuple, list)):\n        value = sum(value[:3]) / 3\n    socket.default_value = value\n\n\ndef eevee_engine():\n    import bpy\n    return \"BLENDER_EEVEE_NEXT\" if bpy.app.version >= (4, 2, 0) else \"BLENDER_EEVEE\"\n\n\ndef set_eevee_property(settings, name, value):\n    parts = name.split(\".\")\n    for part in parts[:-1]:\n        if not hasattr(settings, part):\n            return\n        settings = getattr(settings, part)\n    if hasattr(settings, parts[-1]):\n        setattr(settings, parts[-1], value)\n\n\ndef set_color_property(settings, name, value):\n    try:\n        setattr(settings, name, value)\n    except (TypeError, ValueError):\n        candidates = (\"Filmic\", \"Standard\") if name == \"view_transform\" else (\"Medium High Contrast\", \"None\")\n        for candidate in candidates:\n            try:\n                setattr(settings, name, candidate)\n                return\n            except (TypeError, ValueError):\n                continue\n        raise\n\n\ndef configure_cycles_device(bpy, scene, requested):\n    scene.cycles.device = \"CPU\"\n    scene.render.threads_mode = \"FIXED\"\n    scene.render.threads = 4\n    if requested == \"cpu\":\n        return \"CPU\"\n    prefs = bpy.context.preferences.addons[\"cycles\"].preferences\n    for backend in (\"OPTIX\", \"CUDA\", \"HIP\", \"METAL\"):\n        try:\n            prefs.compute_device_type = backend\n            prefs.get_devices()\n            found = [device for device in prefs.devices if device.type == backend]\n            if found:\n                for device in prefs.devices:\n                    device.use = device.type == backend\n                scene.cycles.device = \"GPU\"\n                return \"GPU\"\n        except (TypeError, RuntimeError, ValueError):\n            continue\n    return \"CPU\"\n", "pcve_legacy_scene": "\"\"\"Original batch/suite workflow for scenes backed by a scenario.json file.\"\"\"\n\nimport argparse\nimport hashlib\nimport importlib\nimport json\nimport random\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\nfrom pcve_scene_runtime import ROOT, add_build_arguments, append_render_options, render_prefix, implementation_hashes, case_outputs\n\nimport pcve_edit_dsl as dsl\n\n\nSCRIPTS = {\n    \"home_basketball_door\": (\"render_home_basketball_door.py\", \"simulate_home_basketball_door.py\"),\n    \"pot_lid_drop\": (\"render_pot_lid_drop.py\", \"simulate_pot_lid_drop.py\"),\n    \"toy_car_bottle\": (\"render_toy_car_bottle.py\", \"simulate_toy_car_bottle.py\"),\n}\n\n\ndef write_json(path, data):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n\n\ndef parser(scene, batch=False):\n    p = argparse.ArgumentParser(description=f\"Build {'randomized samples' if batch else 'a source/edit suite'} for {scene}.\")\n    p.add_argument(\"--out-root\", type=Path, default=ROOT / \"renders\" / (f\"batch_{scene}\" if batch else f\"pcve_{scene}_suite\"))\n    p.add_argument(\"--resolution\", nargs=2, type=int, default=[1280, 720])\n    p.add_argument(\"--fps\", type=int, default=24)\n    p.add_argument(\"--duration-sec\", type=float, default=4.0)\n    p.add_argument(\"--samples\", type=int, default=32)\n    p.add_argument(\"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    p.add_argument(\"--mode\", choices=(\"preview\", \"animation\"), default=\"preview\" if batch else \"animation\")\n    p.add_argument(\"--skip-existing\", action=\"store_true\")\n    p.add_argument(\"--dry-run\", action=\"store_true\")\n    p.add_argument(\"--verbose-render\", action=\"store_true\")\n    p.add_argument(\"--simulate-only\", action=\"store_true\")\n    if batch:\n        p.add_argument(\"--count\", type=int, default=4)\n        p.add_argument(\"--start-index\", type=int, default=0)\n        p.add_argument(\"--seed-base\", type=int, default=7200)\n    else:\n        p.add_argument(\"--cases\", nargs=\"+\")\n        p.add_argument(\"--clean-stale-cases\", action=\"store_true\")\n    return add_build_arguments(p)\n\n\ndef scene_directory(scene):\n    candidates = (ROOT / \"clean_scripts\" / scene, ROOT / \"clean_scripts\" / scene)\n    for directory in candidates:\n        if directory.is_dir():\n            return directory\n    raise FileNotFoundError(f\"No scene directory found for {scene}: {candidates}\")\n\n\ndef command_for(scene, folder, args, seed, overrides):\n    render, simulate = SCRIPTS[scene]\n    directory = scene_directory(scene)\n    if args.simulate_only:\n        command = [str(args.physics_python), str(directory / simulate), \"--out\", str(folder / \"physics_transforms.json\")]\n    else:\n        command = render_prefix(args, directory / render)\n        command += [\"--out-dir\", str(folder), \"--mode\", args.mode,\n                    \"--resolution\", *map(str, args.resolution), \"--samples\", str(args.samples),\n                    \"--physics-python\", str(args.physics_python), \"--seed\", str(seed)]\n        append_render_options(command, args)\n    command += [\"--fps\", str(args.fps), \"--duration-sec\", str(args.duration_sec)]\n    if overrides is not None:\n        command += [\"--scenario-overrides-json\", str(overrides)]\n    return command\n\n\ndef run_case(scene, folder, args, seed, override):\n    folder = folder.resolve()\n    overrides = folder / \"scenario_overrides.json\" if override else None\n    command = command_for(scene, folder, args, seed, overrides)\n    if args.dry_run:\n        print(subprocess.list2cmdline(command))\n        return {\"status\": \"dry_run\"}\n    implementation = implementation_hashes(scene_directory(scene))\n    payload = dict(override=override, implementation=implementation, seed=seed, fps=args.fps,\n                   duration=args.duration_sec, mode=args.mode, samples=args.samples,\n                   resolution=args.resolution, engine=args.engine, device=args.device,\n                   preview_frame=args.preview_frame, simulation_only=args.simulate_only)\n    fp = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()\n    status_path = folder / \"run_status.json\"\n    required = [\"physics_transforms.json\"] if args.simulate_only else [\n        \"ground_truth_transforms.json\", \"scenario_metadata.json\",\n        \"video.mp4\" if args.mode == \"animation\" else \"preview.png\"]\n    if args.skip_existing and status_path.is_file():\n        previous = json.loads(status_path.read_text(encoding=\"utf-8\"))\n        if previous.get(\"fingerprint\") == fp and all((folder / p).is_file() for p in required):\n            return dict(previous, status=\"skipped_existing\")\n    if overrides is not None:\n        write_json(overrides, override)\n    folder.mkdir(parents=True, exist_ok=True)\n    start = time.perf_counter()\n    if args.verbose_render:\n        subprocess.run(command, check=True)\n    else:\n        with (folder / \"render.log\").open(\"w\", encoding=\"utf-8\") as log:\n            subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)\n    for name in required:\n        if not (folder / name).is_file():\n            raise FileNotFoundError(folder / name)\n    status = dict(status=\"completed\", valid=True, fingerprint=fp, simulation_only=args.simulate_only,\n                  render_mode=args.mode, elapsed_sec=round(time.perf_counter() - start, 3),\n                  outputs=case_outputs(folder))\n    write_json(status_path, status)\n    return status\n\n\ndef batch_main(scene, argv=None):\n    args = parser(scene, batch=True).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    if args.count < 1 or args.start_index < 0:\n        raise ValueError(\"Count must be positive and start index nonnegative\")\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    vocab = importlib.import_module(f\"{scene}.edit_vocab\").VOCAB\n    manifest = dict(schema_version=1, scene=scene, mode=args.mode, count=args.count,\n                    start_index=args.start_index, seed_base=args.seed_base, samples=[])\n    for offset in range(args.count):\n        index = args.start_index + offset\n        seed = args.seed_base + index\n        rng = random.Random(seed)\n        params = dict(vocab.baseline_physics)\n        for binding in vocab.sim_bindings.values():\n            if isinstance(binding, dsl.SimBinding) and isinstance(params[binding.key], (int, float)):\n                params[binding.key] *= rng.uniform(.8, 1.2)\n        folder = args.out_root / f\"sample_{index:04d}\"\n        result = run_case(scene, folder, args, seed, {\"physics\": params})\n        manifest[\"samples\"].append(dict(sample_index=index, seed=seed, params=params,\n                                         out_dir=str(folder), **result))\n        if not args.dry_run:\n            write_json(args.out_root / \"batch_manifest.json\", manifest)\n\n\ndef suite_main(scene, argv=None):\n    args = parser(scene).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    module = importlib.import_module(f\"{scene}.edit_vocab\")\n    vocab = module.VOCAB\n    source_id = f\"{scene}_baseline\"\n    cases = list(module.EDIT_CASES)\n    if args.cases:\n        unknown = set(args.cases) - {source_id, *[name for name, _ in cases]}\n        if unknown:\n            raise ValueError(f\"Unknown cases: {sorted(unknown)}\")\n        cases = [(name, instruction) for name, instruction in cases if name in args.cases]\n    if args.clean_stale_cases and not args.dry_run:\n        keep = {source_id, *[name for name, _ in module.EDIT_CASES]}\n        for folder in (args.out_root / \"cases\").glob(\"*\"):\n            if folder.is_dir() and folder.name not in keep:\n                if not folder.resolve().is_relative_to(args.out_root):\n                    raise ValueError(f\"Unsafe case directory: {folder}\")\n                shutil.rmtree(folder)\n    manifest = dict(schema_version=3, suite_name=f\"pcve_{scene}_suite\", scene=scene,\n                    baseline_physics=vocab.baseline_physics, total_frames=round(args.fps * args.duration_sec),\n                    fps=args.fps, duration_sec=args.duration_sec, physical_duration_sec=args.duration_sec,\n                    playback_duration_sec=args.duration_sec, slow_motion=1, sample_fps=args.fps,\n                    samples=args.samples, resolution=args.resolution, source=None, edits=[])\n    path = args.out_root / \"suite_manifest.json\"\n    for index, (case_id, instruction) in enumerate([(source_id, None), *cases]):\n        folder = args.out_root / \"cases\" / case_id\n        record = dict(case_id=case_id, kind=\"edit\" if instruction else \"source\",\n                      case_dir=str(folder), seed=7300 + index, status=\"pending\")\n        override = None\n        if instruction:\n            edit = dsl.parse(instruction, vocab)\n            override = {\"physics\": dsl.to_scenario_override(edit, vocab)}\n            record.update(source_case_id=source_id, edit_dsl=instruction,\n                          edit_summary=\"Change the declared physical parameter and simulate the resulting rigid-body interaction.\",\n                          applies_from_frame=dsl.starts_at_frame(edit), prompts=dsl.make_prompts(edit, vocab),\n                          physics_diff={f\"{edit.property_name} ({edit.object_id})\": {\n                              \"from\": dsl.baseline_value_for(edit, vocab), \"to\": dsl.resolved_to_value(edit, vocab)},\n                              \"timing\": dsl.timing_diff(edit, vocab)})\n            manifest[\"edits\"].append(record)\n        else:\n            record[\"description\"] = module.DESCRIPTION\n            manifest[\"source\"] = record\n        if not args.dry_run:\n            prompts = dict(schema_version=2 if instruction else 1, **record)\n            if not instruction:\n                prompts[\"prompts\"] = module.DESCRIPTION\n            write_json(folder / \"prompts.json\", prompts)\n            write_json(path, manifest)\n        try:\n            record.update(run_case(scene, folder, args, record[\"seed\"], override))\n        except Exception:\n            record[\"status\"] = \"failed\"\n            write_json(path, manifest)\n            raise\n        if not args.dry_run:\n            write_json(path, manifest)\n", "pcve_render_quality": "\"\"\"Appearance render setup only; no simulation settings or shared project edits.\"\"\"\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy,scene,args):\n    scene.render.engine=eevee_engine() if args.engine=='eevee' else 'CYCLES'\n    if args.engine=='eevee':\n        set_eevee_property(scene.eevee, 'taa_render_samples', args.samples);set_eevee_property(scene.eevee, 'use_raytracing', False)\n        set_eevee_property(scene.eevee, 'ray_tracing_options.resolution_scale', '2');set_eevee_property(scene.eevee, 'ray_tracing_options.screen_trace_quality', 0.6)\n        set_eevee_property(scene.eevee, 'use_gtao', True);set_eevee_property(scene.eevee, 'gtao_distance', 0.2);set_eevee_property(scene.eevee, 'gtao_quality', 1.0)\n        set_eevee_property(scene.eevee, 'shadow_ray_count', 1);set_eevee_property(scene.eevee, 'shadow_step_count', 8)\n    else:\n        scene.cycles.samples=args.samples;scene.cycles.use_denoising=True;scene.cycles.max_bounces=8;scene.cycles.diffuse_bounces=4;scene.cycles.glossy_bounces=4\n        scene.cycles.adaptive_threshold=.008;scene.cycles.seed=19;scene.render.use_persistent_data=True\n        # Default 1.5 px pixel filter softens fine background detail; 1.0 keeps the\n        # scanned bookshelf textures crisp without aliasing the suspension threads.\n        scene.cycles.filter_width=1.0\n        scene.cycles.device='CPU'\n        if args.device=='auto':\n            prefs=bpy.context.preferences.addons['cycles'].preferences\n            try:\n                prefs.compute_device_type='CUDA';prefs.get_devices();available=[dev for dev in prefs.devices if dev.type=='CUDA']\n                for dev in prefs.devices:dev.use=(dev.type=='CUDA')\n                if available:\n                    scene.cycles.device='GPU';scene.cycles.denoiser='OPTIX' if any(dev.type=='OPTIX' for dev in prefs.devices) else 'OPENIMAGEDENOISE'\n                    print('[render] CUDA: '+', '.join(dev.name for dev in available),flush=True)\n            except Exception as exc:\n                scene.cycles.device='CPU';scene.cycles.denoiser='OPENIMAGEDENOISE'\n                print('[render] CPU fallback: '+str(exc),flush=True)\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX');set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast');scene.view_settings.exposure=-.22\n\n\ndef prepare_eevee(bpy,scene,moving):\n    if scene.render.engine!=eevee_engine() or bpy.app.version<(4,2,0):return\n    for light in bpy.data.lights:light.use_shadow_jitter=False\n    scene.use_nodes=True;nodes=scene.node_tree.nodes;links=scene.node_tree.links;nodes.clear()\n    layers=nodes.new('CompositorNodeRLayers');denoise=nodes.new('CompositorNodeDenoise');denoise.use_hdr=True\n    composite=nodes.new('CompositorNodeComposite');links.new(layers.outputs['Image'],denoise.inputs['Image']);links.new(denoise.outputs['Image'],composite.inputs['Image'])\n    probe_data=bpy.data.lightprobes.new('Static room irradiance','VOLUME');probe_data.resolution_x=6;probe_data.resolution_y=4;probe_data.resolution_z=4;probe_data.bake_samples=32;probe_data.surfel_density=10\n    probe=bpy.data.objects.new('Static room irradiance',probe_data);scene.collection.objects.link(probe);probe.location=[.2,.5,1.3];probe.scale=[2.5,2.2,1.6]\n    dynamic=list(moving)\n    for obj in list(dynamic):dynamic.extend(obj.children_recursive)\n    dynamic=list(dict.fromkeys(dynamic));previous=[obj.hide_render for obj in dynamic]\n    try:\n        for obj in dynamic:obj.hide_render=True\n        bpy.context.view_layer.objects.active=probe;probe.select_set(True)\n        print('[render] Baking static room indirect light',flush=True);bpy.ops.object.lightprobe_cache_bake(subset='ALL')\n    finally:\n        for obj,hidden in zip(dynamic,previous):obj.hide_render=hidden\n", "scene_support": "", "scene_support.home_basketball_door.door_asset": "\"\"\"Swap the room's painted door for a modelled one, frame included.\n\n``cloe_room.glb`` ships a door that is a **zero-thickness sheet**: 18 vertices,\n20 triangles, all normals +Y, and no material of its own -- the room paints it\nwith whatever texture the wall happens to carry. Solidified to the 45 mm the\nsimulator collides with it renders as a flat card with a ladder of light and\ndark rungs down its edge (see the README's *Known limits*). ``old_door.glb`` is\na real door: panels, mouldings, a lever handle, a threshold, and the casing\nthat goes round it.\n\nThe asset is one mesh holding both the fixed frame and the leaf that stands\najar in it, so this module measures the pair apart and puts each where the\nscene's own door used to be:\n\n* the **leaf** is re-posed into the room's convention -- long axis +X, hinge\n  line at the object's origin, standing on the floor, centred on the collision\n  slab -- so the physics animation keys it exactly as before;\n* with ``frame_style: fitted``, the **frame** is built as thin bevelled trim\n  on the measured wall plane, with separate reveal liners and shared satin\n  paint; the original scaled asset frame remains available as a legacy option.\n\nThe renderer fits the leaf to the measured plaster opening and passes that\nsame hinge slab to the simulator via ``door_leaf.json``. The imported paint\npanels and hardware are fitted to it by ``fit_leaf_to_collision``.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport math\nfrom typing import Any, Iterable\n\nimport bmesh\nimport bpy\nfrom mathutils import Matrix, Vector\n\n# The asset's frame is an axis-aligned hollow box around a leaf that stands\n# 60.84 deg open. Anything within this many asset units of the leaf's plane and\n# not part of the frame's outer skin is leaf -- the handle sticks out 8.9, so\n# the window has to be at least that wide.\nLEAF_SLAB_HALF_WIDTH = 12.0\n# A component that spans the full frame height and sits entirely inside the\n# casing's depth is the frame's jamb liner, however close to the leaf's plane\n# its centroid falls: at the hinge the two are coplanar by construction.\nFULL_HEIGHT_UNITS = 200.0\nCASING_DEPTH_UNITS = 5.6\n\n\ndef _components(mesh: bpy.types.Mesh) -> list[list[int]]:\n    bm = bmesh.new()\n    bm.from_mesh(mesh)\n    bm.verts.ensure_lookup_table()\n    seen: set[int] = set()\n    groups: list[list[int]] = []\n    for vert in bm.verts:\n        if vert.index in seen:\n            continue\n        stack = [vert]\n        seen.add(vert.index)\n        group: list[int] = []\n        while stack:\n            current = stack.pop()\n            group.append(current.index)\n            for edge in current.link_edges:\n                other = edge.other_vert(current)\n                if other.index not in seen:\n                    seen.add(other.index)\n                    stack.append(other)\n        groups.append(group)\n    bm.free()\n    return groups\n\n\ndef _carve(source: bpy.types.Object, keep: set[int], name: str) -> bpy.types.Object:\n    \"\"\"Copy the faces whose vertices are all in ``keep`` into a new object.\"\"\"\n    mesh = source.data.copy()\n    bm = bmesh.new()\n    bm.from_mesh(mesh)\n    bm.verts.ensure_lookup_table()\n    doomed = [v for v in bm.verts if v.index not in keep]\n    bmesh.ops.delete(bm, geom=doomed, context='VERTS')\n    bm.to_mesh(mesh)\n    bm.free()\n    part = bpy.data.objects.new(name, mesh)\n    part.matrix_world = source.matrix_world\n    bpy.context.collection.objects.link(part)\n    return part\n\n\ndef _leaf_plane(verts: list[Vector]) -> tuple[float, Vector, Vector, Vector]:\n    \"\"\"Fit the leaf's plane from the vertices that are furthest from the frame.\n\n    The frame stands in the asset's ``y = 0`` plane and the leaf is swung away\n    from it, so the far third of the point cloud is leaf and nothing else. A 2x2\n    PCA in XY gives the leaf's long axis; the frame is axis-aligned, so the\n    difference between the two axes is the angle the artist left the door open.\n    \"\"\"\n    lo = min(p.y for p in verts)\n    hi = max(p.y for p in verts)\n    cut = lo + 0.65 * (hi - lo)\n    far = [p for p in verts if p.y < cut]\n    cx = sum(p.x for p in far) / len(far)\n    cy = sum(p.y for p in far) / len(far)\n    sxx = sum((p.x - cx) ** 2 for p in far) / len(far)\n    syy = sum((p.y - cy) ** 2 for p in far) / len(far)\n    sxy = sum((p.x - cx) * (p.y - cy) for p in far) / len(far)\n    angle = 0.5 * math.atan2(2.0 * sxy, sxx - syy)\n    u = Vector((math.cos(angle), math.sin(angle), 0.0))\n    n = Vector((-math.sin(angle), math.cos(angle), 0.0))\n    return angle, Vector((cx, cy, 0.0)), u, n\n\n\ndef _split(source: bpy.types.Object) -> tuple[set[int], set[int], dict[str, Any]]:\n    \"\"\"Separate the swinging leaf from the fixed frame, and measure both.\n\n    Two rules, because one is not enough:\n\n    * **distance to the leaf's plane.** The leaf is a slab standing 60.84 deg\n      away from the frame's plane, so everything within 12 units of that plane\n      is leaf -- 12 rather than the slab's own 3.7 because both lever handles\n      hang 6.5 units off the faces.\n    * **the leaf's own height.** Two of the casing's caps -- the top and bottom\n      faces of the right post -- land inside that 12-unit window purely because\n      the post stands where the hinge does, and one of them sits at the asset's\n      z = 264.89, above the leaf's 254.19. Taking the leaf's height from the\n      0.5-99.5 percentile of its own vertices rather than from its extremes\n      drops both, without needing to know the casing's layout first.\n\n    The frame's jamb liner is excluded a third way: it spans the full casing\n    height and stands entirely inside the casing's depth, which at the hinge is\n    exactly where the leaf's plane runs.\n    \"\"\"\n    matrix = source.matrix_world\n    verts = [matrix @ v.co for v in source.data.vertices]\n    angle, origin, u, n = _leaf_plane(verts)\n\n    candidates: list[tuple[list[int], list[Vector]]] = []\n    frame_ids: set[int] = set()\n    for group in _components(source.data):\n        points = [verts[i] for i in group]\n        centre = sum(points, Vector()) / len(points)\n        leaf_distance = abs((centre - origin).dot(n))\n        z_span = max(p.z for p in points) - min(p.z for p in points)\n        inside_casing = max(abs(p.y) for p in points) <= CASING_DEPTH_UNITS\n        is_jamb_liner = z_span > FULL_HEIGHT_UNITS and inside_casing\n        if leaf_distance < LEAF_SLAB_HALF_WIDTH and not is_jamb_liner:\n            candidates.append((group, points))\n        else:\n            frame_ids.update(group)\n\n    zs = sorted(p.z for _group, points in candidates for p in points)\n    lo = zs[int(0.005 * (len(zs) - 1))]\n    hi = zs[int(0.995 * (len(zs) - 1))]\n    leaf_ids: set[int] = set()\n    for group, points in candidates:\n        if max(p.z for p in points) > hi + 2.0 or min(p.z for p in points) < lo - 2.0:\n            frame_ids.update(group)\n        else:\n            leaf_ids.update(group)\n\n    leaf_points = [verts[i] for i in sorted(leaf_ids)]\n    along = [(p - origin).dot(u) for p in leaf_points]\n    across = [(p - origin).dot(n) for p in leaf_points]\n    t_lo, t_hi = min(along), max(along)\n    end_lo = origin + u * t_lo\n    end_hi = origin + u * t_hi\n    # The hinge is the end that stands nearest the frame's own plane.\n    hinge = end_lo if abs(end_lo.y) < abs(end_hi.y) else end_hi\n    across_mid = (min(across) + max(across)) / 2.0\n    measurement = {\n        'angle_rad': angle,\n        'plane_origin': origin,\n        'width_units': t_hi - t_lo,\n        'height_units': max(p.z for p in leaf_points) - min(p.z for p in leaf_points),\n        'z_bottom': min(p.z for p in leaf_points),\n        'thickness_units': max(across) - min(across),\n        'hinge_units': Vector((hinge.x, hinge.y, 0.0)) + n * across_mid,\n    }\n    return leaf_ids, frame_ids, measurement\n\n\ndef _frame_opening(frame: bpy.types.Object) -> dict[str, float]:\n    \"\"\"The frame's own inner opening and outer box, in asset units.\n\n    The casing is a closed hollow box, and only the planes that **span it** are\n    its surfaces. Two things inside it are not:\n\n    * the **door stop**, a liner 3.8 units proud of the right reveal that runs\n      the casing's full height but only a third of its depth;\n    * the **threshold**, a board across the bottom that is deeper and wider than\n      the casing and sits entirely below 1 % of its height.\n\n    Measuring from the nearest plane instead of the spanning one takes the stop\n    for the reveal and the threshold's top for the head, which makes the\n    opening 3.8 units narrow and 252 units short and drops the whole casing two\n    metres into the floor. So: drop everything in the bottom 5 %, and keep only\n    the planes whose cross-section covers at least 70 % of the widest one.\n    \"\"\"\n    matrix = frame.matrix_world\n    verts = [matrix @ v.co for v in frame.data.vertices]\n    lo = Vector((min(p.x for p in verts), min(p.y for p in verts), min(p.z for p in verts)))\n    hi = Vector((max(p.x for p in verts), max(p.y for p in verts), max(p.z for p in verts)))\n    body = [p for p in verts if p.z > lo.z + 0.05 * (hi.z - lo.z)]\n    middle = 0.5 * (lo.x + hi.x)\n\n    def spanning_planes(axis: int, cross_axis: int, minimum_ratio: float) -> list[float]:\n        buckets: dict[float, list[Vector]] = {}\n        for point in body:\n            buckets.setdefault(round(point[axis], 3), []).append(point)\n        extents = {\n            value: max(p[cross_axis] for p in points) - min(p[cross_axis] for p in points)\n            for value, points in buckets.items()\n        }\n        widest = max(extents.values()) if extents else 0.0\n        return sorted(v for v, e in extents.items() if e >= minimum_ratio * widest)\n\n    xs = spanning_planes(0, 1, 0.7)\n    left = [x for x in xs if x < middle]\n    right = [x for x in xs if x > middle]\n    inner_left = max(left) if left else lo.x\n    inner_right = min(right) if right else hi.x\n\n    zs = spanning_planes(2, 0, 0.7)\n    head_zs = [z for z in zs if z > lo.z + 0.05 * (hi.z - lo.z)]\n    return {\n        'outer_lo': lo,\n        'outer_hi': hi,\n        'inner_left': inner_left,\n        'inner_right': inner_right,\n        'inner_top': min(head_zs) if head_zs else hi.z,\n        'inner_bottom': lo.z,\n    }\n\n\ndef _tame_materials(imported: Iterable[bpy.types.Object], emission: float, roughness_floor: float) -> None:\n    \"\"\"Same two fixes the room asset needs: no baked emission, no mirror gloss.\n\n    The door is a painted surface; its atlas also carries the grubby threshold\n    and the stone reveal, so the floor is only applied to materials that come in\n    below it rather than being forced onto every slot.\n    \"\"\"\n    for obj in imported:\n        if obj.type != 'MESH':\n            continue\n        for slot in obj.material_slots:\n            material = slot.material\n            if material is None or not material.use_nodes:\n                continue\n            for node in material.node_tree.nodes:\n                if node.type != 'BSDF_PRINCIPLED':\n                    continue\n                strength = node.inputs.get('Emission Strength')\n                if strength is not None and not strength.is_linked:\n                    strength.default_value = float(emission)\n                rough = node.inputs.get('Roughness')\n                if rough is not None and not rough.is_linked and rough.default_value < roughness_floor:\n                    rough.default_value = float(roughness_floor)\n                metallic = node.inputs.get('Metallic')\n                if metallic is not None and not metallic.is_linked:\n                    metallic.default_value = min(metallic.default_value, 0.05)\n\n\ndef _repose_leaf(\n    leaf: bpy.types.Object,\n    measurement: dict[str, Any],\n    *,\n    width_m: float,\n    height_m: float,\n) -> dict[str, Any]:\n    \"\"\"Put the leaf where the room's own leaf stood: +X, hinge on the origin.\n\n    Order, as everywhere else in this scene: move the hinge to the origin,\n    rotate the artist's open angle away, then scale, then drop onto the floor.\n    The hinge stays at the object's **local** origin rather than at its world\n    position, because the animation keys a single Z rotation and Blender turns an\n    object about its own origin -- bake the world hinge into the mesh instead and\n    the leaf swings about the room's origin, i.e. through the wall.\n    \"\"\"\n    angle = float(measurement['angle_rad'])\n    hinge = Vector(measurement['hinge_units'])\n    width_units = float(measurement['width_units'])\n    height_units = float(measurement['height_units'])\n    z_bottom = float(measurement['z_bottom'])\n\n    scale_z = height_m / height_units\n    # The asset's own leaf is within a millimetre of the room door's aspect, so\n    # the width fit is a 0.4 % nudge, not a stretch. Mirroring X is what turns\n    # the leaf round to point +X from its hinge.\n    scale_x = -width_m / width_units\n\n    transform = (\n        Matrix.Diagonal((scale_x, scale_z, scale_z, 1.0))\n        @ Matrix.Rotation(-angle, 4, 'Z')\n        @ Matrix.Translation(Vector((-hinge.x, -hinge.y, -z_bottom)))\n    )\n    leaf.data.transform(transform)\n    # A negative X scale inverts the winding, so every face would render inside\n    # out -- the leaf would read as a hollow shell with black creases.\n    leaf.data.flip_normals()\n    leaf.data.update()\n    leaf.location = (0.0, 0.0, 0.0)\n    leaf.rotation_mode = 'XYZ'\n\n    posed = [leaf.data.vertices[i].co for i in range(len(leaf.data.vertices))]\n    xs = [p.x for p in posed]\n    ys = [p.y for p in posed]\n    zs = [p.z for p in posed]\n    # Centre the slab on the collision box rather than on its own mouldings: the\n    # handle hangs off one face and would otherwise bias the leaf off the plane\n    # the simulator collides with.\n    mid = (min(ys) + max(ys)) / 2.0\n    shell = [p for p in posed if abs(p.y - mid) < 0.02]\n    if shell:\n        mid = (min(p.y for p in shell) + max(p.y for p in shell)) / 2.0\n    bmesh.ops_hint = None  # keep linters quiet; no-op\n    offset = Vector((0.0, -mid, 0.0))\n    leaf.data.transform(Matrix.Translation(offset))\n    leaf.data.update()\n    posed = [v.co for v in leaf.data.vertices]\n    xs = [p.x for p in posed]\n    ys = [p.y for p in posed]\n    zs = [p.z for p in posed]\n    leaf_info = {\n        'leaf_x_m': [round(min(xs), 4), round(max(xs), 4)],\n        'leaf_y_m': [round(min(ys), 4), round(max(ys), 4)],\n        'leaf_z_m': [round(min(zs), 4), round(max(zs), 4)],\n        'scale_x': round(scale_x, 6),\n        'scale_z': round(scale_z, 6),\n        'slab_offset_m': round(-mid, 5),\n        'asset_open_deg': round(math.degrees(angle), 2),\n    }\n    return leaf_info\n\n\ndef _place_frame(\n    frame: bpy.types.Object,\n    opening: dict[str, float],\n    measurement: dict[str, Any],\n    spec: dict[str, Any],\n    *,\n    leaf_width_m: float,\n    aperture: tuple[Vector, Vector],\n    wall: dict[str, Any] | None,\n    floor_z: float,\n) -> dict[str, Any]:\n    \"\"\"Scale the casing so its architrave frames the aperture, then drop it in.\n\n    Three constraints, in order of hardness:\n\n    * the **inner opening must clear the swinging leaf**, so it is sized from\n      ``frame_opening_width_m`` rather than from the aperture, and must stay\n      wider than the leaf at its smallest opening angle;\n    * the **architrave must cover the aperture's edges** and the thin lip the\n      room asset leaves around them, so the outer box is checked against\n      ``aperture``;\n    * the **front face must sit on the wall**, so the casing reads as trim\n      rather than as a box hanging in the hole. The bedroom's doorway is cut\n      into a splayed panel, so \"on the wall\" means on *that panel's* plane: with\n      ``wall`` supplied the casing is yawed onto the panel's normal, which is\n      what makes its architrave meet the plaster instead of standing off it on\n      one side.\n\n    The asset's frame is proportionally taller than the room's doorway -- 264.9\n    units of casing around a 254.2 opening against 2.08 m of hole -- so the\n    casing is sunk below the floor until its opening head lands on the\n    aperture's top. That is invisible: the legs simply continue under the\n    floorboards, and it buys a uniform scale, hence a uniform architrave.\n    \"\"\"\n    inner_width = opening['inner_right'] - opening['inner_left']\n    inner_height = opening['inner_top'] - opening['inner_bottom']\n    outer_width = opening['outer_hi'].x - opening['outer_lo'].x\n    outer_height = opening['outer_hi'].z - opening['outer_lo'].z\n\n    target_opening = float(spec.get('frame_opening_width_m') or (leaf_width_m + 0.055))\n    scale = target_opening / inner_width\n    if scale <= 0.0:\n        raise RuntimeError('frame inner opening measures zero; the asset has changed')\n\n    aperture_lo, aperture_hi = aperture\n    centre_x = 0.5 * (aperture_lo.x + aperture_hi.x)\n    opening_centre_asset = 0.5 * (opening['inner_left'] + opening['inner_right'])\n    top_z = float(aperture_hi.z)\n\n    depth = spec.get('frame_depth_m')\n    if depth is not None:\n        depth_units = opening['outer_hi'].y - opening['outer_lo'].y\n        scale_y = float(depth) / depth_units\n    else:\n        scale_y = scale\n\n    yaw = float(spec.get('frame_yaw_deg') or 0.0)\n    pivot_asset = Vector((opening_centre_asset, opening['outer_hi'].y, opening['inner_top']))\n    proud = float(spec.get('frame_front_proud_m') or 0.0)\n    if wall is not None:\n        normal = Vector(wall['normal'])\n        yaw = float(wall['yaw_deg'])\n        # Slide the pivot onto the panel's plane along its own normal, so the\n        # architrave's face is coplanar with the plaster however the panel is\n        # turned; then back it off by the proudness.\n        target = Vector((centre_x, 0.0, top_z))\n        target.y = (wall['offset'] - normal.x * target.x) / normal.y\n        target += normal * proud\n    else:\n        front_y = spec.get('frame_front_y_m')\n        if front_y is None:\n            front_y = aperture_hi.y\n        target = Vector((centre_x, float(front_y) + proud, top_z))\n\n    transform = (\n        Matrix.Translation(target)\n        @ Matrix.Rotation(math.radians(yaw), 4, 'Z')\n        @ Matrix.Diagonal((scale, scale_y, scale, 1.0))\n        @ Matrix.Translation(-pivot_asset)\n    )\n    frame.data.transform(transform)\n    frame.data.update()\n    frame.location = (0.0, 0.0, 0.0)\n\n    verts = [v.co for v in frame.data.vertices]\n    lo = Vector((min(p.x for p in verts), min(p.y for p in verts), min(p.z for p in verts)))\n    hi = Vector((max(p.x for p in verts), max(p.y for p in verts), max(p.z for p in verts)))\n    info = {\n        'outer_x_m': [round(lo.x, 4), round(hi.x, 4)],\n        'outer_y_m': [round(lo.y, 4), round(hi.y, 4)],\n        'outer_z_m': [round(lo.z, 4), round(hi.z, 4)],\n        'opening_width_m': round(inner_width * scale, 4),\n        'opening_height_m': round(inner_height * scale, 4),\n        'architrave_width_m': round((outer_width - inner_width) * scale / 2.0, 4),\n        'architrave_head_m': round((outer_height - inner_height) * scale, 4),\n        'depth_m': round((opening['outer_hi'].y - opening['outer_lo'].y) * scale_y, 4),\n        'yaw_deg': round(yaw, 3),\n        'from_wall_plane': wall is not None,\n        'scale': [round(scale, 6), round(scale_y, 6)],\n        'sunk_below_floor_m': round(floor_z - (top_z - inner_height * scale), 4),\n        'leaf_width_m': round(leaf_width_m, 4),\n        'asset_open_deg': round(math.degrees(float(measurement['angle_rad'])), 2),\n    }\n    return info\n\n\ndef _paint_material(spec: dict[str, Any]) -> bpy.types.Material:\n    \"\"\"Satin painted timber, with only a very fine surface grain.\"\"\"\n    material = bpy.data.materials.new('door_satin_paint')\n    material.use_nodes = True\n    nodes = material.node_tree.nodes\n    bsdf = nodes.get('Principled BSDF')\n    bsdf.inputs['Base Color'].default_value = (*spec.get('paint_color', [0.64, 0.61, 0.55]), 1.0)\n    bsdf.inputs['Roughness'].default_value = 0.48\n    noise = nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value = 180.0\n    noise.inputs['Detail'].default_value = 2.0\n    bump = nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value = 0.12\n    bump.inputs['Distance'].default_value = 0.00025\n    material.node_tree.links.new(noise.outputs['Fac'], bump.inputs['Height'])\n    material.node_tree.links.new(bump.outputs['Normal'], bsdf.inputs['Normal'])\n    return material\n\n\ndef _refinish_leaf(leaf: bpy.types.Object, paint: bpy.types.Material, height: float, width: float) -> None:\n    \"\"\"Keep the modelled panels and metalwork; replace the baked dirty paint.\"\"\"\n    paint_index = len(leaf.data.materials)\n    leaf.data.materials.append(paint)\n    hardware: set[int] = set()\n    scraps: set[int] = set()\n    for group in _components(leaf.data):\n        points = [leaf.data.vertices[i].co for i in group]\n        lo = [min(p[k] for p in points) for k in range(3)]\n        hi = [max(p[k] for p in points) for k in range(3)]\n        # Disconnected casing end caps also intersect the leaf's fitted plane.\n        if hi[0] < width * 0.15 and (hi[2] < 0.025 or lo[2] > height - 0.005):\n            scraps.update(group)\n        is_handle = lo[0] > width * 0.75 and lo[2] > height * 0.46 and hi[2] < height * 0.57\n        is_hinge = hi[0] < width * 0.10 and hi[2] - lo[2] < height * 0.04 and lo[2] > 0.1\n        if is_handle or is_hinge:\n            hardware.update(group)\n    for poly in leaf.data.polygons:\n        if not all(i in hardware for i in poly.vertices):\n            poly.material_index = paint_index\n    if scraps:\n        bm = bmesh.new()\n        bm.from_mesh(leaf.data)\n        bm.verts.ensure_lookup_table()\n        bmesh.ops.delete(bm, geom=[bm.verts[i] for i in scraps], context='VERTS')\n        bm.to_mesh(leaf.data)\n        bm.free()\n    leaf.data.update()\n\n\ndef fit_leaf_to_collision(leaf, width, height, thickness, bottom):\n    \"\"\"Fit the painted timber, excluding hardware, to the hinge collision slab.\n\n    The imported casing fragments previously biased the fit, leaving 75 mm\n    of empty space at the hinge and a small yaw error. The large timber faces\n    provide the actual panel axis and bounds. The hinge is on the front edge:\n    local timber spans x=[0,width], y=[-thickness,0].\n    \"\"\"\n    panel = max(leaf.data.polygons, key=lambda p: p.area)\n    normal = panel.normal.copy()\n    if normal.y < 0:\n        normal.negate()\n    yaw = math.atan2(-normal.x, normal.y)\n    leaf.data.transform(Matrix.Rotation(-yaw, 4, 'Z'))\n    leaf.data.update()\n    body_ids = {i for p in leaf.data.polygons if p.area > 0.005 for i in p.vertices}\n    points = [leaf.data.vertices[i].co for i in body_ids]\n    lo = Vector(tuple(min(p[k] for p in points) for k in range(3)))\n    hi = Vector(tuple(max(p[k] for p in points) for k in range(3)))\n    scale = Vector((width / (hi.x - lo.x), thickness / (hi.y - lo.y), height / (hi.z - lo.z)))\n    transform = (Matrix.Translation((0, -thickness, bottom))\n                 @ Matrix.Diagonal((*scale, 1)) @ Matrix.Translation(-lo))\n    leaf.data.transform(transform)\n    leaf.data.update()\n    return {'corrected_panel_yaw_deg': math.degrees(yaw),\n            'body_bounds_local': [[0, width], [-thickness, 0], [bottom, bottom + height]]}\n\n\ndef _fitted_frame(spec, aperture, wall, floor_z, paint):\n    \"\"\"Thin architrave on the plaster plane, independently of the reveal depth.\n\n    The opening is measured in world X, while the trim is measured along the\n    splayed wall. Projecting its width avoids exposing the carved aperture.\n    \"\"\"\n    lo, hi = aperture\n    yaw = math.radians(float(wall['yaw_deg'])) if wall else 0.0\n    normal = Vector(wall['normal']) if wall else Vector((0, 1, 0))\n    centre_x = (lo.x + hi.x) * 0.5\n    front_y = ((wall['offset'] - normal.x * centre_x) / normal.y\n               if wall else float(spec.get('frame_front_y_m', hi.y)))\n    origin = Vector((centre_x, front_y, floor_z))\n    rotation = Matrix.Rotation(yaw, 4, 'Z')\n    half = (hi.x - lo.x) / (2.0 * math.cos(yaw))\n    height = hi.z - floor_z\n    trim = float(spec.get('frame_trim_width_m', 0.065))\n    proud = float(spec.get('frame_front_proud_m', 0.018))\n    parts = []\n\n    def board(name, x0, x1, z0, z1, y0, y1):\n        bpy.ops.mesh.primitive_cube_add(size=1)\n        obj = bpy.context.object\n        obj.name = name\n        obj.dimensions = (x1 - x0, y1 - y0, z1 - z0)\n        bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)\n        obj.location = origin + rotation @ Vector(((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2))\n        obj.rotation_euler.z = yaw\n        obj.data.materials.append(paint)\n        bevel = obj.modifiers.new('Soft painted edges', 'BEVEL')\n        bevel.width = 0.0015\n        bevel.segments = 3\n        obj.modifiers.new('Corner normals', 'WEIGHTED_NORMAL')\n        parts.append(obj)\n\n    # Optional surface architrave; the recessed liners also work on their own.\n    architrave = bool(spec.get('frame_architrave', True))\n    if architrave:\n        for side, a, b in [('left', -half - trim, -half), ('right', half, half + trim)]:\n            board(f'door_frame_{side}', a, b, 0, height, -0.006, proud)\n            bead_a = b - 0.009 if side == 'left' else a\n            board(f'door_frame_{side}_bead', bead_a, bead_a + 0.009, 0, height, proud - 0.002, proud + 0.004)\n        board('door_frame_head', -half - trim, half + trim, height, height + trim, -0.006, proud)\n        board('door_frame_head_bead', -half, half, height, height + 0.009, proud - 0.002, proud + 0.004)\n    # The reveal is a shallow liner behind the trim, never a scaled display box.\n    depth = float(spec.get('frame_reveal_depth_m', 0.075))\n    if not architrave:\n        paint = paint.copy()\n        paint.name = 'door_reveal_plaster'\n        bsdf = paint.node_tree.nodes.get('Principled BSDF')\n        bsdf.inputs['Base Color'].default_value = (*spec.get('reveal_color', [0.52, 0.50, 0.46]), 1.0)\n        bsdf.inputs['Roughness'].default_value = 0.78\n    liner_front = 0.001 if architrave else -0.004\n    for side, a, b in [('left', -half - 0.018, -half), ('right', half, half + 0.018)]:\n        board(f'door_frame_{side}_liner', a, b, 0, height, -depth, liner_front)\n    board('door_frame_head_liner', -half, half, height, height + 0.018, -depth, liner_front)\n    return parts[0], {'construction': 'fitted_trim', 'opening_width_m': round(half * 2, 4),\n                      'opening_height_m': round(height, 4), 'architrave_width_m': trim,\n                      'front_proud_m': proud if architrave else 0.0, 'reveal_depth_m': depth,\n                      'architrave_enabled': architrave,\n                      'yaw_deg': round(math.degrees(yaw), 3)}\n\n\ndef strip_room_casing(\n    room: Iterable[bpy.types.Object],\n    *,\n    box_lo: Vector,\n    box_hi: Vector,\n) -> int:\n    \"\"\"Delete the room asset's own door casing, so the new frame can own the opening.\n\n    ``cloe_room.glb`` builds its doorway as a casing **box**: two architrave\n    faces, a 0.56 m reveal and a stop, all standing proud of the wall on the\n    splayed panel the door is cut into. Dropping the door asset's frame inside\n    that leaves one casing hiding the other -- measured, the room's stands\n    1.8 cm proud, so a frame set flush to the plaster is completely invisible\n    and one set in front of it reads as a second architrave.\n\n    So the room's casing goes. It is identified component by component -- a\n    connected island whose every vertex falls inside the doorway's own box --\n    which keeps the window, which shares the same ``do&win`` mesh, and every\n    wall panel, whose faces run far past that box, untouched.\n    \"\"\"\n    total = 0\n    for obj in room:\n        if obj.type != 'MESH':\n            continue\n        matrix = obj.matrix_world\n        doomed: set[int] = set()\n        for group in _components(obj.data):\n            points = [matrix @ obj.data.vertices[i].co for i in group]\n            if all(\n                box_lo[k] - 1e-4 <= point[k] <= box_hi[k] + 1e-4\n                for point in points\n                for k in range(3)\n            ):\n                doomed.update(group)\n        if not doomed:\n            continue\n        bm = bmesh.new()\n        bm.from_mesh(obj.data)\n        bm.verts.ensure_lookup_table()\n        bmesh.ops.delete(bm, geom=[v for v in bm.verts if v.index in doomed], context='VERTS')\n        bm.to_mesh(obj.data)\n        bm.free()\n        obj.data.update()\n        total += len(doomed)\n        print(f'[door] removed {len(doomed)} casing verts from {obj.name}')\n    print(f'[door] room casing stripped: {total} verts')\n    return total\n\n\ndef build_door_from_asset(\n    path,\n    spec: dict[str, Any],\n    *,\n    leaf_width_m: float,\n    leaf_height_m: float,\n    hinge_world: Vector,\n    floor_z: float,\n    aperture: tuple[Vector, Vector],\n    wall: dict[str, Any] | None = None,\n) -> tuple[bpy.types.Object | None, bpy.types.Object | None, dict[str, Any]]:\n    \"\"\"Import the door asset and return its leaf and frame as scene objects.\"\"\"\n    previous = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    bpy.context.view_layer.update()\n    imported = [o for o in bpy.data.objects if o not in previous]\n    for obj in imported:\n        obj.animation_data_clear()\n    _tame_materials(\n        imported,\n        float(spec.get('emission_scale', 0.0)),\n        float(spec.get('roughness_min', 0.35)),\n    )\n\n    meshes = [o for o in imported if o.type == 'MESH']\n    if len(meshes) != 1:\n        raise RuntimeError(f'{path} has {len(meshes)} meshes; this loader expects one')\n    source = meshes[0]\n    # glTF wraps the mesh in empties that carry the exporter's unit scaling and\n    # the Y-up -> Z-up correction. Everything below is written in the asset's\n    # own world space, so bake that chain into the mesh and cut the parent: left\n    # in place the hinge translation lands in local space and the leaf ends up\n    # 2 m below the floor.\n    world = source.matrix_world.copy()\n    source.parent = None\n    source.data.transform(world)\n    source.matrix_world = Matrix.Identity(4)\n    bpy.context.view_layer.update()\n\n    leaf_ids, frame_ids, measurement = _split(source)\n    print(\n        f'[door] asset {path.name}: leaf {len(leaf_ids)} verts of {len(source.data.vertices)}, '\n        f'frame {len(frame_ids)}, artist left it {math.degrees(measurement[\"angle_rad\"]):.2f} deg open, '\n        f'leaf {measurement[\"width_units\"]:.2f} x {measurement[\"height_units\"]:.2f} units '\n        f'({measurement[\"thickness_units\"]:.2f} thick), hinge at '\n        f'({measurement[\"hinge_units\"].x:.2f}, {measurement[\"hinge_units\"].y:.2f})'\n    )\n\n    leaf = _carve(source, leaf_ids, 'door_leaf')\n    leaf.data.name = 'door_leaf'\n    for slot in source.material_slots:\n        if slot.material is not None and slot.material.name not in leaf.data.materials:\n            leaf.data.materials.append(slot.material)\n\n    leaf_info = _repose_leaf(\n        leaf,\n        measurement,\n        width_m=leaf_width_m,\n        height_m=leaf_height_m,\n    )\n    print(\n        f'[door] leaf -> x{leaf_info[\"leaf_x_m\"]} y{leaf_info[\"leaf_y_m\"]} z{leaf_info[\"leaf_z_m\"]} '\n        f'(scale {leaf_info[\"scale_x\"]:.5f} x {leaf_info[\"scale_z\"]:.5f})'\n    )\n\n    frame = None\n    frame_info: dict[str, Any] = {}\n    fitted = spec.get('frame_style') == 'fitted'\n    paint = _paint_material(spec) if fitted else None\n    if fitted:\n        _refinish_leaf(leaf, paint, leaf_height_m, leaf_width_m)\n    keep_frame = bool(spec.get('frame_enabled', True))\n    if keep_frame and fitted:\n        frame, frame_info = _fitted_frame(spec, aperture, wall, floor_z, paint)\n        print(f'[door] fitted frame: {frame_info}')\n    elif keep_frame and frame_ids:\n        frame = _carve(source, frame_ids, 'door_frame')\n        frame.data.name = 'door_frame'\n        for slot in source.material_slots:\n            if slot.material is not None and slot.material.name not in frame.data.materials:\n                frame.data.materials.append(slot.material)\n        opening = _frame_opening(frame)\n        frame_info = _place_frame(\n            frame,\n            opening,\n            measurement,\n            spec,\n            leaf_width_m=leaf_width_m,\n            aperture=aperture,\n            wall=wall,\n            floor_z=floor_z,\n        )\n        print(\n            f'[door] frame -> x{frame_info[\"outer_x_m\"]} y{frame_info[\"outer_y_m\"]} '\n            f'z{frame_info[\"outer_z_m\"]}, opening {frame_info[\"opening_width_m\"]:.3f} x '\n            f'{frame_info[\"opening_height_m\"]:.3f} m, architrave {frame_info[\"architrave_width_m\"]:.3f} m '\n            f'side / {frame_info[\"architrave_head_m\"]:.3f} m head, yaw {frame_info[\"yaw_deg\"]:+.2f} deg, '\n            f'sunk {frame_info[\"sunk_below_floor_m\"]:.3f} m'\n        )\n\n    for obj in imported:\n        if obj is not leaf and obj is not frame and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj, do_unlink=True)\n    bpy.context.view_layer.update()\n    return leaf, frame, {'leaf': leaf_info, 'frame': frame_info}\n", "scene_support.home_basketball_door.scenario_io": "\"\"\"Shared scenario loading for the home_basketball_door scene.\n\n``scenario.json`` holds three blocks -- ``assets``, ``physics`` and\n``layout`` -- and every entry point (simulator, renderer, PCVE builder) reads\nit through here, so a case's override file is merged exactly one way: group by\ngroup, key by key, with nested dicts merged recursively and everything else\nreplaced wholesale.\n\nAn override file is therefore the same shape as ``scenario.json`` with only the\nkeys that differ, e.g. ``{\"physics\": {\"lid_mass\": 0.9}}``. That is also the\nshape ``build_pcve_home_basketball_door.py`` writes for each edit case.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport copy\nimport json\nfrom pathlib import Path\nfrom typing import Any\n\nSCENE_DIR = _PCVE_ROOT / 'assets' / 'scenarios' / 'home_basketball_door'\nSCENARIO_PATH = SCENE_DIR / 'scenario.json'\n\nGROUPS = ('assets', 'physics', 'layout')\n\n\ndef read_json(path: Path) -> dict[str, Any]:\n    data = json.loads(Path(path).expanduser().read_text(encoding='utf-8'))\n    if not isinstance(data, dict):\n        raise ValueError(f'Expected a JSON object: {path}')\n    return data\n\n\ndef merge(base: dict[str, Any], updates: dict[str, Any]) -> dict[str, Any]:\n    merged = copy.deepcopy(base)\n    for key, value in updates.items():\n        if isinstance(value, dict) and isinstance(merged.get(key), dict):\n            merged[key] = merge(merged[key], value)\n        else:\n            merged[key] = copy.deepcopy(value)\n    return merged\n\n\ndef load_scenario(\n    scenario_path: Path | None = None,\n    overrides_path: Path | None = None,\n) -> dict[str, Any]:\n    \"\"\"Baseline scenario, with an optional overrides file merged on top.\"\"\"\n    scenario = read_json(scenario_path or SCENARIO_PATH)\n    for group in GROUPS:\n        scenario.setdefault(group, {})\n    if overrides_path is not None:\n        scenario = merge(scenario, read_json(overrides_path))\n        scenario['overrides_path'] = str(Path(overrides_path).expanduser().resolve())\n    return scenario\n\n\ndef write_json(path: Path, payload: Any) -> None:\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding='utf-8')\n", "scene_support.home_basketball_door": "\"\"\"Shared support modules for home_basketball_door.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n", "door_asset": "\"\"\"Swap the room's painted door for a modelled one, frame included.\n\n``cloe_room.glb`` ships a door that is a **zero-thickness sheet**: 18 vertices,\n20 triangles, all normals +Y, and no material of its own -- the room paints it\nwith whatever texture the wall happens to carry. Solidified to the 45 mm the\nsimulator collides with it renders as a flat card with a ladder of light and\ndark rungs down its edge (see the README's *Known limits*). ``old_door.glb`` is\na real door: panels, mouldings, a lever handle, a threshold, and the casing\nthat goes round it.\n\nThe asset is one mesh holding both the fixed frame and the leaf that stands\najar in it, so this module measures the pair apart and puts each where the\nscene's own door used to be:\n\n* the **leaf** is re-posed into the room's convention -- long axis +X, hinge\n  line at the object's origin, standing on the floor, centred on the collision\n  slab -- so the physics animation keys it exactly as before;\n* with ``frame_style: fitted``, the **frame** is built as thin bevelled trim\n  on the measured wall plane, with separate reveal liners and shared satin\n  paint; the original scaled asset frame remains available as a legacy option.\n\nThe renderer fits the leaf to the measured plaster opening and passes that\nsame hinge slab to the simulator via ``door_leaf.json``. The imported paint\npanels and hardware are fitted to it by ``fit_leaf_to_collision``.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport math\nfrom typing import Any, Iterable\n\nimport bmesh\nimport bpy\nfrom mathutils import Matrix, Vector\n\n# The asset's frame is an axis-aligned hollow box around a leaf that stands\n# 60.84 deg open. Anything within this many asset units of the leaf's plane and\n# not part of the frame's outer skin is leaf -- the handle sticks out 8.9, so\n# the window has to be at least that wide.\nLEAF_SLAB_HALF_WIDTH = 12.0\n# A component that spans the full frame height and sits entirely inside the\n# casing's depth is the frame's jamb liner, however close to the leaf's plane\n# its centroid falls: at the hinge the two are coplanar by construction.\nFULL_HEIGHT_UNITS = 200.0\nCASING_DEPTH_UNITS = 5.6\n\n\ndef _components(mesh: bpy.types.Mesh) -> list[list[int]]:\n    bm = bmesh.new()\n    bm.from_mesh(mesh)\n    bm.verts.ensure_lookup_table()\n    seen: set[int] = set()\n    groups: list[list[int]] = []\n    for vert in bm.verts:\n        if vert.index in seen:\n            continue\n        stack = [vert]\n        seen.add(vert.index)\n        group: list[int] = []\n        while stack:\n            current = stack.pop()\n            group.append(current.index)\n            for edge in current.link_edges:\n                other = edge.other_vert(current)\n                if other.index not in seen:\n                    seen.add(other.index)\n                    stack.append(other)\n        groups.append(group)\n    bm.free()\n    return groups\n\n\ndef _carve(source: bpy.types.Object, keep: set[int], name: str) -> bpy.types.Object:\n    \"\"\"Copy the faces whose vertices are all in ``keep`` into a new object.\"\"\"\n    mesh = source.data.copy()\n    bm = bmesh.new()\n    bm.from_mesh(mesh)\n    bm.verts.ensure_lookup_table()\n    doomed = [v for v in bm.verts if v.index not in keep]\n    bmesh.ops.delete(bm, geom=doomed, context='VERTS')\n    bm.to_mesh(mesh)\n    bm.free()\n    part = bpy.data.objects.new(name, mesh)\n    part.matrix_world = source.matrix_world\n    bpy.context.collection.objects.link(part)\n    return part\n\n\ndef _leaf_plane(verts: list[Vector]) -> tuple[float, Vector, Vector, Vector]:\n    \"\"\"Fit the leaf's plane from the vertices that are furthest from the frame.\n\n    The frame stands in the asset's ``y = 0`` plane and the leaf is swung away\n    from it, so the far third of the point cloud is leaf and nothing else. A 2x2\n    PCA in XY gives the leaf's long axis; the frame is axis-aligned, so the\n    difference between the two axes is the angle the artist left the door open.\n    \"\"\"\n    lo = min(p.y for p in verts)\n    hi = max(p.y for p in verts)\n    cut = lo + 0.65 * (hi - lo)\n    far = [p for p in verts if p.y < cut]\n    cx = sum(p.x for p in far) / len(far)\n    cy = sum(p.y for p in far) / len(far)\n    sxx = sum((p.x - cx) ** 2 for p in far) / len(far)\n    syy = sum((p.y - cy) ** 2 for p in far) / len(far)\n    sxy = sum((p.x - cx) * (p.y - cy) for p in far) / len(far)\n    angle = 0.5 * math.atan2(2.0 * sxy, sxx - syy)\n    u = Vector((math.cos(angle), math.sin(angle), 0.0))\n    n = Vector((-math.sin(angle), math.cos(angle), 0.0))\n    return angle, Vector((cx, cy, 0.0)), u, n\n\n\ndef _split(source: bpy.types.Object) -> tuple[set[int], set[int], dict[str, Any]]:\n    \"\"\"Separate the swinging leaf from the fixed frame, and measure both.\n\n    Two rules, because one is not enough:\n\n    * **distance to the leaf's plane.** The leaf is a slab standing 60.84 deg\n      away from the frame's plane, so everything within 12 units of that plane\n      is leaf -- 12 rather than the slab's own 3.7 because both lever handles\n      hang 6.5 units off the faces.\n    * **the leaf's own height.** Two of the casing's caps -- the top and bottom\n      faces of the right post -- land inside that 12-unit window purely because\n      the post stands where the hinge does, and one of them sits at the asset's\n      z = 264.89, above the leaf's 254.19. Taking the leaf's height from the\n      0.5-99.5 percentile of its own vertices rather than from its extremes\n      drops both, without needing to know the casing's layout first.\n\n    The frame's jamb liner is excluded a third way: it spans the full casing\n    height and stands entirely inside the casing's depth, which at the hinge is\n    exactly where the leaf's plane runs.\n    \"\"\"\n    matrix = source.matrix_world\n    verts = [matrix @ v.co for v in source.data.vertices]\n    angle, origin, u, n = _leaf_plane(verts)\n\n    candidates: list[tuple[list[int], list[Vector]]] = []\n    frame_ids: set[int] = set()\n    for group in _components(source.data):\n        points = [verts[i] for i in group]\n        centre = sum(points, Vector()) / len(points)\n        leaf_distance = abs((centre - origin).dot(n))\n        z_span = max(p.z for p in points) - min(p.z for p in points)\n        inside_casing = max(abs(p.y) for p in points) <= CASING_DEPTH_UNITS\n        is_jamb_liner = z_span > FULL_HEIGHT_UNITS and inside_casing\n        if leaf_distance < LEAF_SLAB_HALF_WIDTH and not is_jamb_liner:\n            candidates.append((group, points))\n        else:\n            frame_ids.update(group)\n\n    zs = sorted(p.z for _group, points in candidates for p in points)\n    lo = zs[int(0.005 * (len(zs) - 1))]\n    hi = zs[int(0.995 * (len(zs) - 1))]\n    leaf_ids: set[int] = set()\n    for group, points in candidates:\n        if max(p.z for p in points) > hi + 2.0 or min(p.z for p in points) < lo - 2.0:\n            frame_ids.update(group)\n        else:\n            leaf_ids.update(group)\n\n    leaf_points = [verts[i] for i in sorted(leaf_ids)]\n    along = [(p - origin).dot(u) for p in leaf_points]\n    across = [(p - origin).dot(n) for p in leaf_points]\n    t_lo, t_hi = min(along), max(along)\n    end_lo = origin + u * t_lo\n    end_hi = origin + u * t_hi\n    # The hinge is the end that stands nearest the frame's own plane.\n    hinge = end_lo if abs(end_lo.y) < abs(end_hi.y) else end_hi\n    across_mid = (min(across) + max(across)) / 2.0\n    measurement = {\n        'angle_rad': angle,\n        'plane_origin': origin,\n        'width_units': t_hi - t_lo,\n        'height_units': max(p.z for p in leaf_points) - min(p.z for p in leaf_points),\n        'z_bottom': min(p.z for p in leaf_points),\n        'thickness_units': max(across) - min(across),\n        'hinge_units': Vector((hinge.x, hinge.y, 0.0)) + n * across_mid,\n    }\n    return leaf_ids, frame_ids, measurement\n\n\ndef _frame_opening(frame: bpy.types.Object) -> dict[str, float]:\n    \"\"\"The frame's own inner opening and outer box, in asset units.\n\n    The casing is a closed hollow box, and only the planes that **span it** are\n    its surfaces. Two things inside it are not:\n\n    * the **door stop**, a liner 3.8 units proud of the right reveal that runs\n      the casing's full height but only a third of its depth;\n    * the **threshold**, a board across the bottom that is deeper and wider than\n      the casing and sits entirely below 1 % of its height.\n\n    Measuring from the nearest plane instead of the spanning one takes the stop\n    for the reveal and the threshold's top for the head, which makes the\n    opening 3.8 units narrow and 252 units short and drops the whole casing two\n    metres into the floor. So: drop everything in the bottom 5 %, and keep only\n    the planes whose cross-section covers at least 70 % of the widest one.\n    \"\"\"\n    matrix = frame.matrix_world\n    verts = [matrix @ v.co for v in frame.data.vertices]\n    lo = Vector((min(p.x for p in verts), min(p.y for p in verts), min(p.z for p in verts)))\n    hi = Vector((max(p.x for p in verts), max(p.y for p in verts), max(p.z for p in verts)))\n    body = [p for p in verts if p.z > lo.z + 0.05 * (hi.z - lo.z)]\n    middle = 0.5 * (lo.x + hi.x)\n\n    def spanning_planes(axis: int, cross_axis: int, minimum_ratio: float) -> list[float]:\n        buckets: dict[float, list[Vector]] = {}\n        for point in body:\n            buckets.setdefault(round(point[axis], 3), []).append(point)\n        extents = {\n            value: max(p[cross_axis] for p in points) - min(p[cross_axis] for p in points)\n            for value, points in buckets.items()\n        }\n        widest = max(extents.values()) if extents else 0.0\n        return sorted(v for v, e in extents.items() if e >= minimum_ratio * widest)\n\n    xs = spanning_planes(0, 1, 0.7)\n    left = [x for x in xs if x < middle]\n    right = [x for x in xs if x > middle]\n    inner_left = max(left) if left else lo.x\n    inner_right = min(right) if right else hi.x\n\n    zs = spanning_planes(2, 0, 0.7)\n    head_zs = [z for z in zs if z > lo.z + 0.05 * (hi.z - lo.z)]\n    return {\n        'outer_lo': lo,\n        'outer_hi': hi,\n        'inner_left': inner_left,\n        'inner_right': inner_right,\n        'inner_top': min(head_zs) if head_zs else hi.z,\n        'inner_bottom': lo.z,\n    }\n\n\ndef _tame_materials(imported: Iterable[bpy.types.Object], emission: float, roughness_floor: float) -> None:\n    \"\"\"Same two fixes the room asset needs: no baked emission, no mirror gloss.\n\n    The door is a painted surface; its atlas also carries the grubby threshold\n    and the stone reveal, so the floor is only applied to materials that come in\n    below it rather than being forced onto every slot.\n    \"\"\"\n    for obj in imported:\n        if obj.type != 'MESH':\n            continue\n        for slot in obj.material_slots:\n            material = slot.material\n            if material is None or not material.use_nodes:\n                continue\n            for node in material.node_tree.nodes:\n                if node.type != 'BSDF_PRINCIPLED':\n                    continue\n                strength = node.inputs.get('Emission Strength')\n                if strength is not None and not strength.is_linked:\n                    strength.default_value = float(emission)\n                rough = node.inputs.get('Roughness')\n                if rough is not None and not rough.is_linked and rough.default_value < roughness_floor:\n                    rough.default_value = float(roughness_floor)\n                metallic = node.inputs.get('Metallic')\n                if metallic is not None and not metallic.is_linked:\n                    metallic.default_value = min(metallic.default_value, 0.05)\n\n\ndef _repose_leaf(\n    leaf: bpy.types.Object,\n    measurement: dict[str, Any],\n    *,\n    width_m: float,\n    height_m: float,\n) -> dict[str, Any]:\n    \"\"\"Put the leaf where the room's own leaf stood: +X, hinge on the origin.\n\n    Order, as everywhere else in this scene: move the hinge to the origin,\n    rotate the artist's open angle away, then scale, then drop onto the floor.\n    The hinge stays at the object's **local** origin rather than at its world\n    position, because the animation keys a single Z rotation and Blender turns an\n    object about its own origin -- bake the world hinge into the mesh instead and\n    the leaf swings about the room's origin, i.e. through the wall.\n    \"\"\"\n    angle = float(measurement['angle_rad'])\n    hinge = Vector(measurement['hinge_units'])\n    width_units = float(measurement['width_units'])\n    height_units = float(measurement['height_units'])\n    z_bottom = float(measurement['z_bottom'])\n\n    scale_z = height_m / height_units\n    # The asset's own leaf is within a millimetre of the room door's aspect, so\n    # the width fit is a 0.4 % nudge, not a stretch. Mirroring X is what turns\n    # the leaf round to point +X from its hinge.\n    scale_x = -width_m / width_units\n\n    transform = (\n        Matrix.Diagonal((scale_x, scale_z, scale_z, 1.0))\n        @ Matrix.Rotation(-angle, 4, 'Z')\n        @ Matrix.Translation(Vector((-hinge.x, -hinge.y, -z_bottom)))\n    )\n    leaf.data.transform(transform)\n    # A negative X scale inverts the winding, so every face would render inside\n    # out -- the leaf would read as a hollow shell with black creases.\n    leaf.data.flip_normals()\n    leaf.data.update()\n    leaf.location = (0.0, 0.0, 0.0)\n    leaf.rotation_mode = 'XYZ'\n\n    posed = [leaf.data.vertices[i].co for i in range(len(leaf.data.vertices))]\n    xs = [p.x for p in posed]\n    ys = [p.y for p in posed]\n    zs = [p.z for p in posed]\n    # Centre the slab on the collision box rather than on its own mouldings: the\n    # handle hangs off one face and would otherwise bias the leaf off the plane\n    # the simulator collides with.\n    mid = (min(ys) + max(ys)) / 2.0\n    shell = [p for p in posed if abs(p.y - mid) < 0.02]\n    if shell:\n        mid = (min(p.y for p in shell) + max(p.y for p in shell)) / 2.0\n    bmesh.ops_hint = None  # keep linters quiet; no-op\n    offset = Vector((0.0, -mid, 0.0))\n    leaf.data.transform(Matrix.Translation(offset))\n    leaf.data.update()\n    posed = [v.co for v in leaf.data.vertices]\n    xs = [p.x for p in posed]\n    ys = [p.y for p in posed]\n    zs = [p.z for p in posed]\n    leaf_info = {\n        'leaf_x_m': [round(min(xs), 4), round(max(xs), 4)],\n        'leaf_y_m': [round(min(ys), 4), round(max(ys), 4)],\n        'leaf_z_m': [round(min(zs), 4), round(max(zs), 4)],\n        'scale_x': round(scale_x, 6),\n        'scale_z': round(scale_z, 6),\n        'slab_offset_m': round(-mid, 5),\n        'asset_open_deg': round(math.degrees(angle), 2),\n    }\n    return leaf_info\n\n\ndef _place_frame(\n    frame: bpy.types.Object,\n    opening: dict[str, float],\n    measurement: dict[str, Any],\n    spec: dict[str, Any],\n    *,\n    leaf_width_m: float,\n    aperture: tuple[Vector, Vector],\n    wall: dict[str, Any] | None,\n    floor_z: float,\n) -> dict[str, Any]:\n    \"\"\"Scale the casing so its architrave frames the aperture, then drop it in.\n\n    Three constraints, in order of hardness:\n\n    * the **inner opening must clear the swinging leaf**, so it is sized from\n      ``frame_opening_width_m`` rather than from the aperture, and must stay\n      wider than the leaf at its smallest opening angle;\n    * the **architrave must cover the aperture's edges** and the thin lip the\n      room asset leaves around them, so the outer box is checked against\n      ``aperture``;\n    * the **front face must sit on the wall**, so the casing reads as trim\n      rather than as a box hanging in the hole. The bedroom's doorway is cut\n      into a splayed panel, so \"on the wall\" means on *that panel's* plane: with\n      ``wall`` supplied the casing is yawed onto the panel's normal, which is\n      what makes its architrave meet the plaster instead of standing off it on\n      one side.\n\n    The asset's frame is proportionally taller than the room's doorway -- 264.9\n    units of casing around a 254.2 opening against 2.08 m of hole -- so the\n    casing is sunk below the floor until its opening head lands on the\n    aperture's top. That is invisible: the legs simply continue under the\n    floorboards, and it buys a uniform scale, hence a uniform architrave.\n    \"\"\"\n    inner_width = opening['inner_right'] - opening['inner_left']\n    inner_height = opening['inner_top'] - opening['inner_bottom']\n    outer_width = opening['outer_hi'].x - opening['outer_lo'].x\n    outer_height = opening['outer_hi'].z - opening['outer_lo'].z\n\n    target_opening = float(spec.get('frame_opening_width_m') or (leaf_width_m + 0.055))\n    scale = target_opening / inner_width\n    if scale <= 0.0:\n        raise RuntimeError('frame inner opening measures zero; the asset has changed')\n\n    aperture_lo, aperture_hi = aperture\n    centre_x = 0.5 * (aperture_lo.x + aperture_hi.x)\n    opening_centre_asset = 0.5 * (opening['inner_left'] + opening['inner_right'])\n    top_z = float(aperture_hi.z)\n\n    depth = spec.get('frame_depth_m')\n    if depth is not None:\n        depth_units = opening['outer_hi'].y - opening['outer_lo'].y\n        scale_y = float(depth) / depth_units\n    else:\n        scale_y = scale\n\n    yaw = float(spec.get('frame_yaw_deg') or 0.0)\n    pivot_asset = Vector((opening_centre_asset, opening['outer_hi'].y, opening['inner_top']))\n    proud = float(spec.get('frame_front_proud_m') or 0.0)\n    if wall is not None:\n        normal = Vector(wall['normal'])\n        yaw = float(wall['yaw_deg'])\n        # Slide the pivot onto the panel's plane along its own normal, so the\n        # architrave's face is coplanar with the plaster however the panel is\n        # turned; then back it off by the proudness.\n        target = Vector((centre_x, 0.0, top_z))\n        target.y = (wall['offset'] - normal.x * target.x) / normal.y\n        target += normal * proud\n    else:\n        front_y = spec.get('frame_front_y_m')\n        if front_y is None:\n            front_y = aperture_hi.y\n        target = Vector((centre_x, float(front_y) + proud, top_z))\n\n    transform = (\n        Matrix.Translation(target)\n        @ Matrix.Rotation(math.radians(yaw), 4, 'Z')\n        @ Matrix.Diagonal((scale, scale_y, scale, 1.0))\n        @ Matrix.Translation(-pivot_asset)\n    )\n    frame.data.transform(transform)\n    frame.data.update()\n    frame.location = (0.0, 0.0, 0.0)\n\n    verts = [v.co for v in frame.data.vertices]\n    lo = Vector((min(p.x for p in verts), min(p.y for p in verts), min(p.z for p in verts)))\n    hi = Vector((max(p.x for p in verts), max(p.y for p in verts), max(p.z for p in verts)))\n    info = {\n        'outer_x_m': [round(lo.x, 4), round(hi.x, 4)],\n        'outer_y_m': [round(lo.y, 4), round(hi.y, 4)],\n        'outer_z_m': [round(lo.z, 4), round(hi.z, 4)],\n        'opening_width_m': round(inner_width * scale, 4),\n        'opening_height_m': round(inner_height * scale, 4),\n        'architrave_width_m': round((outer_width - inner_width) * scale / 2.0, 4),\n        'architrave_head_m': round((outer_height - inner_height) * scale, 4),\n        'depth_m': round((opening['outer_hi'].y - opening['outer_lo'].y) * scale_y, 4),\n        'yaw_deg': round(yaw, 3),\n        'from_wall_plane': wall is not None,\n        'scale': [round(scale, 6), round(scale_y, 6)],\n        'sunk_below_floor_m': round(floor_z - (top_z - inner_height * scale), 4),\n        'leaf_width_m': round(leaf_width_m, 4),\n        'asset_open_deg': round(math.degrees(float(measurement['angle_rad'])), 2),\n    }\n    return info\n\n\ndef _paint_material(spec: dict[str, Any]) -> bpy.types.Material:\n    \"\"\"Satin painted timber, with only a very fine surface grain.\"\"\"\n    material = bpy.data.materials.new('door_satin_paint')\n    material.use_nodes = True\n    nodes = material.node_tree.nodes\n    bsdf = nodes.get('Principled BSDF')\n    bsdf.inputs['Base Color'].default_value = (*spec.get('paint_color', [0.64, 0.61, 0.55]), 1.0)\n    bsdf.inputs['Roughness'].default_value = 0.48\n    noise = nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value = 180.0\n    noise.inputs['Detail'].default_value = 2.0\n    bump = nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value = 0.12\n    bump.inputs['Distance'].default_value = 0.00025\n    material.node_tree.links.new(noise.outputs['Fac'], bump.inputs['Height'])\n    material.node_tree.links.new(bump.outputs['Normal'], bsdf.inputs['Normal'])\n    return material\n\n\ndef _refinish_leaf(leaf: bpy.types.Object, paint: bpy.types.Material, height: float, width: float) -> None:\n    \"\"\"Keep the modelled panels and metalwork; replace the baked dirty paint.\"\"\"\n    paint_index = len(leaf.data.materials)\n    leaf.data.materials.append(paint)\n    hardware: set[int] = set()\n    scraps: set[int] = set()\n    for group in _components(leaf.data):\n        points = [leaf.data.vertices[i].co for i in group]\n        lo = [min(p[k] for p in points) for k in range(3)]\n        hi = [max(p[k] for p in points) for k in range(3)]\n        # Disconnected casing end caps also intersect the leaf's fitted plane.\n        if hi[0] < width * 0.15 and (hi[2] < 0.025 or lo[2] > height - 0.005):\n            scraps.update(group)\n        is_handle = lo[0] > width * 0.75 and lo[2] > height * 0.46 and hi[2] < height * 0.57\n        is_hinge = hi[0] < width * 0.10 and hi[2] - lo[2] < height * 0.04 and lo[2] > 0.1\n        if is_handle or is_hinge:\n            hardware.update(group)\n    for poly in leaf.data.polygons:\n        if not all(i in hardware for i in poly.vertices):\n            poly.material_index = paint_index\n    if scraps:\n        bm = bmesh.new()\n        bm.from_mesh(leaf.data)\n        bm.verts.ensure_lookup_table()\n        bmesh.ops.delete(bm, geom=[bm.verts[i] for i in scraps], context='VERTS')\n        bm.to_mesh(leaf.data)\n        bm.free()\n    leaf.data.update()\n\n\ndef fit_leaf_to_collision(leaf, width, height, thickness, bottom):\n    \"\"\"Fit the painted timber, excluding hardware, to the hinge collision slab.\n\n    The imported casing fragments previously biased the fit, leaving 75 mm\n    of empty space at the hinge and a small yaw error. The large timber faces\n    provide the actual panel axis and bounds. The hinge is on the front edge:\n    local timber spans x=[0,width], y=[-thickness,0].\n    \"\"\"\n    panel = max(leaf.data.polygons, key=lambda p: p.area)\n    normal = panel.normal.copy()\n    if normal.y < 0:\n        normal.negate()\n    yaw = math.atan2(-normal.x, normal.y)\n    leaf.data.transform(Matrix.Rotation(-yaw, 4, 'Z'))\n    leaf.data.update()\n    body_ids = {i for p in leaf.data.polygons if p.area > 0.005 for i in p.vertices}\n    points = [leaf.data.vertices[i].co for i in body_ids]\n    lo = Vector(tuple(min(p[k] for p in points) for k in range(3)))\n    hi = Vector(tuple(max(p[k] for p in points) for k in range(3)))\n    scale = Vector((width / (hi.x - lo.x), thickness / (hi.y - lo.y), height / (hi.z - lo.z)))\n    transform = (Matrix.Translation((0, -thickness, bottom))\n                 @ Matrix.Diagonal((*scale, 1)) @ Matrix.Translation(-lo))\n    leaf.data.transform(transform)\n    leaf.data.update()\n    return {'corrected_panel_yaw_deg': math.degrees(yaw),\n            'body_bounds_local': [[0, width], [-thickness, 0], [bottom, bottom + height]]}\n\n\ndef _fitted_frame(spec, aperture, wall, floor_z, paint):\n    \"\"\"Thin architrave on the plaster plane, independently of the reveal depth.\n\n    The opening is measured in world X, while the trim is measured along the\n    splayed wall. Projecting its width avoids exposing the carved aperture.\n    \"\"\"\n    lo, hi = aperture\n    yaw = math.radians(float(wall['yaw_deg'])) if wall else 0.0\n    normal = Vector(wall['normal']) if wall else Vector((0, 1, 0))\n    centre_x = (lo.x + hi.x) * 0.5\n    front_y = ((wall['offset'] - normal.x * centre_x) / normal.y\n               if wall else float(spec.get('frame_front_y_m', hi.y)))\n    origin = Vector((centre_x, front_y, floor_z))\n    rotation = Matrix.Rotation(yaw, 4, 'Z')\n    half = (hi.x - lo.x) / (2.0 * math.cos(yaw))\n    height = hi.z - floor_z\n    trim = float(spec.get('frame_trim_width_m', 0.065))\n    proud = float(spec.get('frame_front_proud_m', 0.018))\n    parts = []\n\n    def board(name, x0, x1, z0, z1, y0, y1):\n        bpy.ops.mesh.primitive_cube_add(size=1)\n        obj = bpy.context.object\n        obj.name = name\n        obj.dimensions = (x1 - x0, y1 - y0, z1 - z0)\n        bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)\n        obj.location = origin + rotation @ Vector(((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2))\n        obj.rotation_euler.z = yaw\n        obj.data.materials.append(paint)\n        bevel = obj.modifiers.new('Soft painted edges', 'BEVEL')\n        bevel.width = 0.0015\n        bevel.segments = 3\n        obj.modifiers.new('Corner normals', 'WEIGHTED_NORMAL')\n        parts.append(obj)\n\n    # Optional surface architrave; the recessed liners also work on their own.\n    architrave = bool(spec.get('frame_architrave', True))\n    if architrave:\n        for side, a, b in [('left', -half - trim, -half), ('right', half, half + trim)]:\n            board(f'door_frame_{side}', a, b, 0, height, -0.006, proud)\n            bead_a = b - 0.009 if side == 'left' else a\n            board(f'door_frame_{side}_bead', bead_a, bead_a + 0.009, 0, height, proud - 0.002, proud + 0.004)\n        board('door_frame_head', -half - trim, half + trim, height, height + trim, -0.006, proud)\n        board('door_frame_head_bead', -half, half, height, height + 0.009, proud - 0.002, proud + 0.004)\n    # The reveal is a shallow liner behind the trim, never a scaled display box.\n    depth = float(spec.get('frame_reveal_depth_m', 0.075))\n    if not architrave:\n        paint = paint.copy()\n        paint.name = 'door_reveal_plaster'\n        bsdf = paint.node_tree.nodes.get('Principled BSDF')\n        bsdf.inputs['Base Color'].default_value = (*spec.get('reveal_color', [0.52, 0.50, 0.46]), 1.0)\n        bsdf.inputs['Roughness'].default_value = 0.78\n    liner_front = 0.001 if architrave else -0.004\n    for side, a, b in [('left', -half - 0.018, -half), ('right', half, half + 0.018)]:\n        board(f'door_frame_{side}_liner', a, b, 0, height, -depth, liner_front)\n    board('door_frame_head_liner', -half, half, height, height + 0.018, -depth, liner_front)\n    return parts[0], {'construction': 'fitted_trim', 'opening_width_m': round(half * 2, 4),\n                      'opening_height_m': round(height, 4), 'architrave_width_m': trim,\n                      'front_proud_m': proud if architrave else 0.0, 'reveal_depth_m': depth,\n                      'architrave_enabled': architrave,\n                      'yaw_deg': round(math.degrees(yaw), 3)}\n\n\ndef strip_room_casing(\n    room: Iterable[bpy.types.Object],\n    *,\n    box_lo: Vector,\n    box_hi: Vector,\n) -> int:\n    \"\"\"Delete the room asset's own door casing, so the new frame can own the opening.\n\n    ``cloe_room.glb`` builds its doorway as a casing **box**: two architrave\n    faces, a 0.56 m reveal and a stop, all standing proud of the wall on the\n    splayed panel the door is cut into. Dropping the door asset's frame inside\n    that leaves one casing hiding the other -- measured, the room's stands\n    1.8 cm proud, so a frame set flush to the plaster is completely invisible\n    and one set in front of it reads as a second architrave.\n\n    So the room's casing goes. It is identified component by component -- a\n    connected island whose every vertex falls inside the doorway's own box --\n    which keeps the window, which shares the same ``do&win`` mesh, and every\n    wall panel, whose faces run far past that box, untouched.\n    \"\"\"\n    total = 0\n    for obj in room:\n        if obj.type != 'MESH':\n            continue\n        matrix = obj.matrix_world\n        doomed: set[int] = set()\n        for group in _components(obj.data):\n            points = [matrix @ obj.data.vertices[i].co for i in group]\n            if all(\n                box_lo[k] - 1e-4 <= point[k] <= box_hi[k] + 1e-4\n                for point in points\n                for k in range(3)\n            ):\n                doomed.update(group)\n        if not doomed:\n            continue\n        bm = bmesh.new()\n        bm.from_mesh(obj.data)\n        bm.verts.ensure_lookup_table()\n        bmesh.ops.delete(bm, geom=[v for v in bm.verts if v.index in doomed], context='VERTS')\n        bm.to_mesh(obj.data)\n        bm.free()\n        obj.data.update()\n        total += len(doomed)\n        print(f'[door] removed {len(doomed)} casing verts from {obj.name}')\n    print(f'[door] room casing stripped: {total} verts')\n    return total\n\n\ndef build_door_from_asset(\n    path,\n    spec: dict[str, Any],\n    *,\n    leaf_width_m: float,\n    leaf_height_m: float,\n    hinge_world: Vector,\n    floor_z: float,\n    aperture: tuple[Vector, Vector],\n    wall: dict[str, Any] | None = None,\n) -> tuple[bpy.types.Object | None, bpy.types.Object | None, dict[str, Any]]:\n    \"\"\"Import the door asset and return its leaf and frame as scene objects.\"\"\"\n    previous = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    bpy.context.view_layer.update()\n    imported = [o for o in bpy.data.objects if o not in previous]\n    for obj in imported:\n        obj.animation_data_clear()\n    _tame_materials(\n        imported,\n        float(spec.get('emission_scale', 0.0)),\n        float(spec.get('roughness_min', 0.35)),\n    )\n\n    meshes = [o for o in imported if o.type == 'MESH']\n    if len(meshes) != 1:\n        raise RuntimeError(f'{path} has {len(meshes)} meshes; this loader expects one')\n    source = meshes[0]\n    # glTF wraps the mesh in empties that carry the exporter's unit scaling and\n    # the Y-up -> Z-up correction. Everything below is written in the asset's\n    # own world space, so bake that chain into the mesh and cut the parent: left\n    # in place the hinge translation lands in local space and the leaf ends up\n    # 2 m below the floor.\n    world = source.matrix_world.copy()\n    source.parent = None\n    source.data.transform(world)\n    source.matrix_world = Matrix.Identity(4)\n    bpy.context.view_layer.update()\n\n    leaf_ids, frame_ids, measurement = _split(source)\n    print(\n        f'[door] asset {path.name}: leaf {len(leaf_ids)} verts of {len(source.data.vertices)}, '\n        f'frame {len(frame_ids)}, artist left it {math.degrees(measurement[\"angle_rad\"]):.2f} deg open, '\n        f'leaf {measurement[\"width_units\"]:.2f} x {measurement[\"height_units\"]:.2f} units '\n        f'({measurement[\"thickness_units\"]:.2f} thick), hinge at '\n        f'({measurement[\"hinge_units\"].x:.2f}, {measurement[\"hinge_units\"].y:.2f})'\n    )\n\n    leaf = _carve(source, leaf_ids, 'door_leaf')\n    leaf.data.name = 'door_leaf'\n    for slot in source.material_slots:\n        if slot.material is not None and slot.material.name not in leaf.data.materials:\n            leaf.data.materials.append(slot.material)\n\n    leaf_info = _repose_leaf(\n        leaf,\n        measurement,\n        width_m=leaf_width_m,\n        height_m=leaf_height_m,\n    )\n    print(\n        f'[door] leaf -> x{leaf_info[\"leaf_x_m\"]} y{leaf_info[\"leaf_y_m\"]} z{leaf_info[\"leaf_z_m\"]} '\n        f'(scale {leaf_info[\"scale_x\"]:.5f} x {leaf_info[\"scale_z\"]:.5f})'\n    )\n\n    frame = None\n    frame_info: dict[str, Any] = {}\n    fitted = spec.get('frame_style') == 'fitted'\n    paint = _paint_material(spec) if fitted else None\n    if fitted:\n        _refinish_leaf(leaf, paint, leaf_height_m, leaf_width_m)\n    keep_frame = bool(spec.get('frame_enabled', True))\n    if keep_frame and fitted:\n        frame, frame_info = _fitted_frame(spec, aperture, wall, floor_z, paint)\n        print(f'[door] fitted frame: {frame_info}')\n    elif keep_frame and frame_ids:\n        frame = _carve(source, frame_ids, 'door_frame')\n        frame.data.name = 'door_frame'\n        for slot in source.material_slots:\n            if slot.material is not None and slot.material.name not in frame.data.materials:\n                frame.data.materials.append(slot.material)\n        opening = _frame_opening(frame)\n        frame_info = _place_frame(\n            frame,\n            opening,\n            measurement,\n            spec,\n            leaf_width_m=leaf_width_m,\n            aperture=aperture,\n            wall=wall,\n            floor_z=floor_z,\n        )\n        print(\n            f'[door] frame -> x{frame_info[\"outer_x_m\"]} y{frame_info[\"outer_y_m\"]} '\n            f'z{frame_info[\"outer_z_m\"]}, opening {frame_info[\"opening_width_m\"]:.3f} x '\n            f'{frame_info[\"opening_height_m\"]:.3f} m, architrave {frame_info[\"architrave_width_m\"]:.3f} m '\n            f'side / {frame_info[\"architrave_head_m\"]:.3f} m head, yaw {frame_info[\"yaw_deg\"]:+.2f} deg, '\n            f'sunk {frame_info[\"sunk_below_floor_m\"]:.3f} m'\n        )\n\n    for obj in imported:\n        if obj is not leaf and obj is not frame and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj, do_unlink=True)\n    bpy.context.view_layer.update()\n    return leaf, frame, {'leaf': leaf_info, 'frame': frame_info}\n", "scenario_io": "\"\"\"Shared scenario loading for the home_basketball_door scene.\n\n``scenario.json`` holds three blocks -- ``assets``, ``physics`` and\n``layout`` -- and every entry point (simulator, renderer, PCVE builder) reads\nit through here, so a case's override file is merged exactly one way: group by\ngroup, key by key, with nested dicts merged recursively and everything else\nreplaced wholesale.\n\nAn override file is therefore the same shape as ``scenario.json`` with only the\nkeys that differ, e.g. ``{\"physics\": {\"lid_mass\": 0.9}}``. That is also the\nshape ``build_pcve_home_basketball_door.py`` writes for each edit case.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport copy\nimport json\nfrom pathlib import Path\nfrom typing import Any\n\nSCENE_DIR = _PCVE_ROOT / 'assets' / 'scenarios' / 'home_basketball_door'\nSCENARIO_PATH = SCENE_DIR / 'scenario.json'\n\nGROUPS = ('assets', 'physics', 'layout')\n\n\ndef read_json(path: Path) -> dict[str, Any]:\n    data = json.loads(Path(path).expanduser().read_text(encoding='utf-8'))\n    if not isinstance(data, dict):\n        raise ValueError(f'Expected a JSON object: {path}')\n    return data\n\n\ndef merge(base: dict[str, Any], updates: dict[str, Any]) -> dict[str, Any]:\n    merged = copy.deepcopy(base)\n    for key, value in updates.items():\n        if isinstance(value, dict) and isinstance(merged.get(key), dict):\n            merged[key] = merge(merged[key], value)\n        else:\n            merged[key] = copy.deepcopy(value)\n    return merged\n\n\ndef load_scenario(\n    scenario_path: Path | None = None,\n    overrides_path: Path | None = None,\n) -> dict[str, Any]:\n    \"\"\"Baseline scenario, with an optional overrides file merged on top.\"\"\"\n    scenario = read_json(scenario_path or SCENARIO_PATH)\n    for group in GROUPS:\n        scenario.setdefault(group, {})\n    if overrides_path is not None:\n        scenario = merge(scenario, read_json(overrides_path))\n        scenario['overrides_path'] = str(Path(overrides_path).expanduser().resolve())\n    return scenario\n\n\ndef write_json(path: Path, payload: Any) -> None:\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding='utf-8')\n", "home_basketball_door.door_asset": "\"\"\"Swap the room's painted door for a modelled one, frame included.\n\n``cloe_room.glb`` ships a door that is a **zero-thickness sheet**: 18 vertices,\n20 triangles, all normals +Y, and no material of its own -- the room paints it\nwith whatever texture the wall happens to carry. Solidified to the 45 mm the\nsimulator collides with it renders as a flat card with a ladder of light and\ndark rungs down its edge (see the README's *Known limits*). ``old_door.glb`` is\na real door: panels, mouldings, a lever handle, a threshold, and the casing\nthat goes round it.\n\nThe asset is one mesh holding both the fixed frame and the leaf that stands\najar in it, so this module measures the pair apart and puts each where the\nscene's own door used to be:\n\n* the **leaf** is re-posed into the room's convention -- long axis +X, hinge\n  line at the object's origin, standing on the floor, centred on the collision\n  slab -- so the physics animation keys it exactly as before;\n* with ``frame_style: fitted``, the **frame** is built as thin bevelled trim\n  on the measured wall plane, with separate reveal liners and shared satin\n  paint; the original scaled asset frame remains available as a legacy option.\n\nThe renderer fits the leaf to the measured plaster opening and passes that\nsame hinge slab to the simulator via ``door_leaf.json``. The imported paint\npanels and hardware are fitted to it by ``fit_leaf_to_collision``.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport math\nfrom typing import Any, Iterable\n\nimport bmesh\nimport bpy\nfrom mathutils import Matrix, Vector\n\n# The asset's frame is an axis-aligned hollow box around a leaf that stands\n# 60.84 deg open. Anything within this many asset units of the leaf's plane and\n# not part of the frame's outer skin is leaf -- the handle sticks out 8.9, so\n# the window has to be at least that wide.\nLEAF_SLAB_HALF_WIDTH = 12.0\n# A component that spans the full frame height and sits entirely inside the\n# casing's depth is the frame's jamb liner, however close to the leaf's plane\n# its centroid falls: at the hinge the two are coplanar by construction.\nFULL_HEIGHT_UNITS = 200.0\nCASING_DEPTH_UNITS = 5.6\n\n\ndef _components(mesh: bpy.types.Mesh) -> list[list[int]]:\n    bm = bmesh.new()\n    bm.from_mesh(mesh)\n    bm.verts.ensure_lookup_table()\n    seen: set[int] = set()\n    groups: list[list[int]] = []\n    for vert in bm.verts:\n        if vert.index in seen:\n            continue\n        stack = [vert]\n        seen.add(vert.index)\n        group: list[int] = []\n        while stack:\n            current = stack.pop()\n            group.append(current.index)\n            for edge in current.link_edges:\n                other = edge.other_vert(current)\n                if other.index not in seen:\n                    seen.add(other.index)\n                    stack.append(other)\n        groups.append(group)\n    bm.free()\n    return groups\n\n\ndef _carve(source: bpy.types.Object, keep: set[int], name: str) -> bpy.types.Object:\n    \"\"\"Copy the faces whose vertices are all in ``keep`` into a new object.\"\"\"\n    mesh = source.data.copy()\n    bm = bmesh.new()\n    bm.from_mesh(mesh)\n    bm.verts.ensure_lookup_table()\n    doomed = [v for v in bm.verts if v.index not in keep]\n    bmesh.ops.delete(bm, geom=doomed, context='VERTS')\n    bm.to_mesh(mesh)\n    bm.free()\n    part = bpy.data.objects.new(name, mesh)\n    part.matrix_world = source.matrix_world\n    bpy.context.collection.objects.link(part)\n    return part\n\n\ndef _leaf_plane(verts: list[Vector]) -> tuple[float, Vector, Vector, Vector]:\n    \"\"\"Fit the leaf's plane from the vertices that are furthest from the frame.\n\n    The frame stands in the asset's ``y = 0`` plane and the leaf is swung away\n    from it, so the far third of the point cloud is leaf and nothing else. A 2x2\n    PCA in XY gives the leaf's long axis; the frame is axis-aligned, so the\n    difference between the two axes is the angle the artist left the door open.\n    \"\"\"\n    lo = min(p.y for p in verts)\n    hi = max(p.y for p in verts)\n    cut = lo + 0.65 * (hi - lo)\n    far = [p for p in verts if p.y < cut]\n    cx = sum(p.x for p in far) / len(far)\n    cy = sum(p.y for p in far) / len(far)\n    sxx = sum((p.x - cx) ** 2 for p in far) / len(far)\n    syy = sum((p.y - cy) ** 2 for p in far) / len(far)\n    sxy = sum((p.x - cx) * (p.y - cy) for p in far) / len(far)\n    angle = 0.5 * math.atan2(2.0 * sxy, sxx - syy)\n    u = Vector((math.cos(angle), math.sin(angle), 0.0))\n    n = Vector((-math.sin(angle), math.cos(angle), 0.0))\n    return angle, Vector((cx, cy, 0.0)), u, n\n\n\ndef _split(source: bpy.types.Object) -> tuple[set[int], set[int], dict[str, Any]]:\n    \"\"\"Separate the swinging leaf from the fixed frame, and measure both.\n\n    Two rules, because one is not enough:\n\n    * **distance to the leaf's plane.** The leaf is a slab standing 60.84 deg\n      away from the frame's plane, so everything within 12 units of that plane\n      is leaf -- 12 rather than the slab's own 3.7 because both lever handles\n      hang 6.5 units off the faces.\n    * **the leaf's own height.** Two of the casing's caps -- the top and bottom\n      faces of the right post -- land inside that 12-unit window purely because\n      the post stands where the hinge does, and one of them sits at the asset's\n      z = 264.89, above the leaf's 254.19. Taking the leaf's height from the\n      0.5-99.5 percentile of its own vertices rather than from its extremes\n      drops both, without needing to know the casing's layout first.\n\n    The frame's jamb liner is excluded a third way: it spans the full casing\n    height and stands entirely inside the casing's depth, which at the hinge is\n    exactly where the leaf's plane runs.\n    \"\"\"\n    matrix = source.matrix_world\n    verts = [matrix @ v.co for v in source.data.vertices]\n    angle, origin, u, n = _leaf_plane(verts)\n\n    candidates: list[tuple[list[int], list[Vector]]] = []\n    frame_ids: set[int] = set()\n    for group in _components(source.data):\n        points = [verts[i] for i in group]\n        centre = sum(points, Vector()) / len(points)\n        leaf_distance = abs((centre - origin).dot(n))\n        z_span = max(p.z for p in points) - min(p.z for p in points)\n        inside_casing = max(abs(p.y) for p in points) <= CASING_DEPTH_UNITS\n        is_jamb_liner = z_span > FULL_HEIGHT_UNITS and inside_casing\n        if leaf_distance < LEAF_SLAB_HALF_WIDTH and not is_jamb_liner:\n            candidates.append((group, points))\n        else:\n            frame_ids.update(group)\n\n    zs = sorted(p.z for _group, points in candidates for p in points)\n    lo = zs[int(0.005 * (len(zs) - 1))]\n    hi = zs[int(0.995 * (len(zs) - 1))]\n    leaf_ids: set[int] = set()\n    for group, points in candidates:\n        if max(p.z for p in points) > hi + 2.0 or min(p.z for p in points) < lo - 2.0:\n            frame_ids.update(group)\n        else:\n            leaf_ids.update(group)\n\n    leaf_points = [verts[i] for i in sorted(leaf_ids)]\n    along = [(p - origin).dot(u) for p in leaf_points]\n    across = [(p - origin).dot(n) for p in leaf_points]\n    t_lo, t_hi = min(along), max(along)\n    end_lo = origin + u * t_lo\n    end_hi = origin + u * t_hi\n    # The hinge is the end that stands nearest the frame's own plane.\n    hinge = end_lo if abs(end_lo.y) < abs(end_hi.y) else end_hi\n    across_mid = (min(across) + max(across)) / 2.0\n    measurement = {\n        'angle_rad': angle,\n        'plane_origin': origin,\n        'width_units': t_hi - t_lo,\n        'height_units': max(p.z for p in leaf_points) - min(p.z for p in leaf_points),\n        'z_bottom': min(p.z for p in leaf_points),\n        'thickness_units': max(across) - min(across),\n        'hinge_units': Vector((hinge.x, hinge.y, 0.0)) + n * across_mid,\n    }\n    return leaf_ids, frame_ids, measurement\n\n\ndef _frame_opening(frame: bpy.types.Object) -> dict[str, float]:\n    \"\"\"The frame's own inner opening and outer box, in asset units.\n\n    The casing is a closed hollow box, and only the planes that **span it** are\n    its surfaces. Two things inside it are not:\n\n    * the **door stop**, a liner 3.8 units proud of the right reveal that runs\n      the casing's full height but only a third of its depth;\n    * the **threshold**, a board across the bottom that is deeper and wider than\n      the casing and sits entirely below 1 % of its height.\n\n    Measuring from the nearest plane instead of the spanning one takes the stop\n    for the reveal and the threshold's top for the head, which makes the\n    opening 3.8 units narrow and 252 units short and drops the whole casing two\n    metres into the floor. So: drop everything in the bottom 5 %, and keep only\n    the planes whose cross-section covers at least 70 % of the widest one.\n    \"\"\"\n    matrix = frame.matrix_world\n    verts = [matrix @ v.co for v in frame.data.vertices]\n    lo = Vector((min(p.x for p in verts), min(p.y for p in verts), min(p.z for p in verts)))\n    hi = Vector((max(p.x for p in verts), max(p.y for p in verts), max(p.z for p in verts)))\n    body = [p for p in verts if p.z > lo.z + 0.05 * (hi.z - lo.z)]\n    middle = 0.5 * (lo.x + hi.x)\n\n    def spanning_planes(axis: int, cross_axis: int, minimum_ratio: float) -> list[float]:\n        buckets: dict[float, list[Vector]] = {}\n        for point in body:\n            buckets.setdefault(round(point[axis], 3), []).append(point)\n        extents = {\n            value: max(p[cross_axis] for p in points) - min(p[cross_axis] for p in points)\n            for value, points in buckets.items()\n        }\n        widest = max(extents.values()) if extents else 0.0\n        return sorted(v for v, e in extents.items() if e >= minimum_ratio * widest)\n\n    xs = spanning_planes(0, 1, 0.7)\n    left = [x for x in xs if x < middle]\n    right = [x for x in xs if x > middle]\n    inner_left = max(left) if left else lo.x\n    inner_right = min(right) if right else hi.x\n\n    zs = spanning_planes(2, 0, 0.7)\n    head_zs = [z for z in zs if z > lo.z + 0.05 * (hi.z - lo.z)]\n    return {\n        'outer_lo': lo,\n        'outer_hi': hi,\n        'inner_left': inner_left,\n        'inner_right': inner_right,\n        'inner_top': min(head_zs) if head_zs else hi.z,\n        'inner_bottom': lo.z,\n    }\n\n\ndef _tame_materials(imported: Iterable[bpy.types.Object], emission: float, roughness_floor: float) -> None:\n    \"\"\"Same two fixes the room asset needs: no baked emission, no mirror gloss.\n\n    The door is a painted surface; its atlas also carries the grubby threshold\n    and the stone reveal, so the floor is only applied to materials that come in\n    below it rather than being forced onto every slot.\n    \"\"\"\n    for obj in imported:\n        if obj.type != 'MESH':\n            continue\n        for slot in obj.material_slots:\n            material = slot.material\n            if material is None or not material.use_nodes:\n                continue\n            for node in material.node_tree.nodes:\n                if node.type != 'BSDF_PRINCIPLED':\n                    continue\n                strength = node.inputs.get('Emission Strength')\n                if strength is not None and not strength.is_linked:\n                    strength.default_value = float(emission)\n                rough = node.inputs.get('Roughness')\n                if rough is not None and not rough.is_linked and rough.default_value < roughness_floor:\n                    rough.default_value = float(roughness_floor)\n                metallic = node.inputs.get('Metallic')\n                if metallic is not None and not metallic.is_linked:\n                    metallic.default_value = min(metallic.default_value, 0.05)\n\n\ndef _repose_leaf(\n    leaf: bpy.types.Object,\n    measurement: dict[str, Any],\n    *,\n    width_m: float,\n    height_m: float,\n) -> dict[str, Any]:\n    \"\"\"Put the leaf where the room's own leaf stood: +X, hinge on the origin.\n\n    Order, as everywhere else in this scene: move the hinge to the origin,\n    rotate the artist's open angle away, then scale, then drop onto the floor.\n    The hinge stays at the object's **local** origin rather than at its world\n    position, because the animation keys a single Z rotation and Blender turns an\n    object about its own origin -- bake the world hinge into the mesh instead and\n    the leaf swings about the room's origin, i.e. through the wall.\n    \"\"\"\n    angle = float(measurement['angle_rad'])\n    hinge = Vector(measurement['hinge_units'])\n    width_units = float(measurement['width_units'])\n    height_units = float(measurement['height_units'])\n    z_bottom = float(measurement['z_bottom'])\n\n    scale_z = height_m / height_units\n    # The asset's own leaf is within a millimetre of the room door's aspect, so\n    # the width fit is a 0.4 % nudge, not a stretch. Mirroring X is what turns\n    # the leaf round to point +X from its hinge.\n    scale_x = -width_m / width_units\n\n    transform = (\n        Matrix.Diagonal((scale_x, scale_z, scale_z, 1.0))\n        @ Matrix.Rotation(-angle, 4, 'Z')\n        @ Matrix.Translation(Vector((-hinge.x, -hinge.y, -z_bottom)))\n    )\n    leaf.data.transform(transform)\n    # A negative X scale inverts the winding, so every face would render inside\n    # out -- the leaf would read as a hollow shell with black creases.\n    leaf.data.flip_normals()\n    leaf.data.update()\n    leaf.location = (0.0, 0.0, 0.0)\n    leaf.rotation_mode = 'XYZ'\n\n    posed = [leaf.data.vertices[i].co for i in range(len(leaf.data.vertices))]\n    xs = [p.x for p in posed]\n    ys = [p.y for p in posed]\n    zs = [p.z for p in posed]\n    # Centre the slab on the collision box rather than on its own mouldings: the\n    # handle hangs off one face and would otherwise bias the leaf off the plane\n    # the simulator collides with.\n    mid = (min(ys) + max(ys)) / 2.0\n    shell = [p for p in posed if abs(p.y - mid) < 0.02]\n    if shell:\n        mid = (min(p.y for p in shell) + max(p.y for p in shell)) / 2.0\n    bmesh.ops_hint = None  # keep linters quiet; no-op\n    offset = Vector((0.0, -mid, 0.0))\n    leaf.data.transform(Matrix.Translation(offset))\n    leaf.data.update()\n    posed = [v.co for v in leaf.data.vertices]\n    xs = [p.x for p in posed]\n    ys = [p.y for p in posed]\n    zs = [p.z for p in posed]\n    leaf_info = {\n        'leaf_x_m': [round(min(xs), 4), round(max(xs), 4)],\n        'leaf_y_m': [round(min(ys), 4), round(max(ys), 4)],\n        'leaf_z_m': [round(min(zs), 4), round(max(zs), 4)],\n        'scale_x': round(scale_x, 6),\n        'scale_z': round(scale_z, 6),\n        'slab_offset_m': round(-mid, 5),\n        'asset_open_deg': round(math.degrees(angle), 2),\n    }\n    return leaf_info\n\n\ndef _place_frame(\n    frame: bpy.types.Object,\n    opening: dict[str, float],\n    measurement: dict[str, Any],\n    spec: dict[str, Any],\n    *,\n    leaf_width_m: float,\n    aperture: tuple[Vector, Vector],\n    wall: dict[str, Any] | None,\n    floor_z: float,\n) -> dict[str, Any]:\n    \"\"\"Scale the casing so its architrave frames the aperture, then drop it in.\n\n    Three constraints, in order of hardness:\n\n    * the **inner opening must clear the swinging leaf**, so it is sized from\n      ``frame_opening_width_m`` rather than from the aperture, and must stay\n      wider than the leaf at its smallest opening angle;\n    * the **architrave must cover the aperture's edges** and the thin lip the\n      room asset leaves around them, so the outer box is checked against\n      ``aperture``;\n    * the **front face must sit on the wall**, so the casing reads as trim\n      rather than as a box hanging in the hole. The bedroom's doorway is cut\n      into a splayed panel, so \"on the wall\" means on *that panel's* plane: with\n      ``wall`` supplied the casing is yawed onto the panel's normal, which is\n      what makes its architrave meet the plaster instead of standing off it on\n      one side.\n\n    The asset's frame is proportionally taller than the room's doorway -- 264.9\n    units of casing around a 254.2 opening against 2.08 m of hole -- so the\n    casing is sunk below the floor until its opening head lands on the\n    aperture's top. That is invisible: the legs simply continue under the\n    floorboards, and it buys a uniform scale, hence a uniform architrave.\n    \"\"\"\n    inner_width = opening['inner_right'] - opening['inner_left']\n    inner_height = opening['inner_top'] - opening['inner_bottom']\n    outer_width = opening['outer_hi'].x - opening['outer_lo'].x\n    outer_height = opening['outer_hi'].z - opening['outer_lo'].z\n\n    target_opening = float(spec.get('frame_opening_width_m') or (leaf_width_m + 0.055))\n    scale = target_opening / inner_width\n    if scale <= 0.0:\n        raise RuntimeError('frame inner opening measures zero; the asset has changed')\n\n    aperture_lo, aperture_hi = aperture\n    centre_x = 0.5 * (aperture_lo.x + aperture_hi.x)\n    opening_centre_asset = 0.5 * (opening['inner_left'] + opening['inner_right'])\n    top_z = float(aperture_hi.z)\n\n    depth = spec.get('frame_depth_m')\n    if depth is not None:\n        depth_units = opening['outer_hi'].y - opening['outer_lo'].y\n        scale_y = float(depth) / depth_units\n    else:\n        scale_y = scale\n\n    yaw = float(spec.get('frame_yaw_deg') or 0.0)\n    pivot_asset = Vector((opening_centre_asset, opening['outer_hi'].y, opening['inner_top']))\n    proud = float(spec.get('frame_front_proud_m') or 0.0)\n    if wall is not None:\n        normal = Vector(wall['normal'])\n        yaw = float(wall['yaw_deg'])\n        # Slide the pivot onto the panel's plane along its own normal, so the\n        # architrave's face is coplanar with the plaster however the panel is\n        # turned; then back it off by the proudness.\n        target = Vector((centre_x, 0.0, top_z))\n        target.y = (wall['offset'] - normal.x * target.x) / normal.y\n        target += normal * proud\n    else:\n        front_y = spec.get('frame_front_y_m')\n        if front_y is None:\n            front_y = aperture_hi.y\n        target = Vector((centre_x, float(front_y) + proud, top_z))\n\n    transform = (\n        Matrix.Translation(target)\n        @ Matrix.Rotation(math.radians(yaw), 4, 'Z')\n        @ Matrix.Diagonal((scale, scale_y, scale, 1.0))\n        @ Matrix.Translation(-pivot_asset)\n    )\n    frame.data.transform(transform)\n    frame.data.update()\n    frame.location = (0.0, 0.0, 0.0)\n\n    verts = [v.co for v in frame.data.vertices]\n    lo = Vector((min(p.x for p in verts), min(p.y for p in verts), min(p.z for p in verts)))\n    hi = Vector((max(p.x for p in verts), max(p.y for p in verts), max(p.z for p in verts)))\n    info = {\n        'outer_x_m': [round(lo.x, 4), round(hi.x, 4)],\n        'outer_y_m': [round(lo.y, 4), round(hi.y, 4)],\n        'outer_z_m': [round(lo.z, 4), round(hi.z, 4)],\n        'opening_width_m': round(inner_width * scale, 4),\n        'opening_height_m': round(inner_height * scale, 4),\n        'architrave_width_m': round((outer_width - inner_width) * scale / 2.0, 4),\n        'architrave_head_m': round((outer_height - inner_height) * scale, 4),\n        'depth_m': round((opening['outer_hi'].y - opening['outer_lo'].y) * scale_y, 4),\n        'yaw_deg': round(yaw, 3),\n        'from_wall_plane': wall is not None,\n        'scale': [round(scale, 6), round(scale_y, 6)],\n        'sunk_below_floor_m': round(floor_z - (top_z - inner_height * scale), 4),\n        'leaf_width_m': round(leaf_width_m, 4),\n        'asset_open_deg': round(math.degrees(float(measurement['angle_rad'])), 2),\n    }\n    return info\n\n\ndef _paint_material(spec: dict[str, Any]) -> bpy.types.Material:\n    \"\"\"Satin painted timber, with only a very fine surface grain.\"\"\"\n    material = bpy.data.materials.new('door_satin_paint')\n    material.use_nodes = True\n    nodes = material.node_tree.nodes\n    bsdf = nodes.get('Principled BSDF')\n    bsdf.inputs['Base Color'].default_value = (*spec.get('paint_color', [0.64, 0.61, 0.55]), 1.0)\n    bsdf.inputs['Roughness'].default_value = 0.48\n    noise = nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value = 180.0\n    noise.inputs['Detail'].default_value = 2.0\n    bump = nodes.new('ShaderNodeBump')\n    bump.inputs['Strength'].default_value = 0.12\n    bump.inputs['Distance'].default_value = 0.00025\n    material.node_tree.links.new(noise.outputs['Fac'], bump.inputs['Height'])\n    material.node_tree.links.new(bump.outputs['Normal'], bsdf.inputs['Normal'])\n    return material\n\n\ndef _refinish_leaf(leaf: bpy.types.Object, paint: bpy.types.Material, height: float, width: float) -> None:\n    \"\"\"Keep the modelled panels and metalwork; replace the baked dirty paint.\"\"\"\n    paint_index = len(leaf.data.materials)\n    leaf.data.materials.append(paint)\n    hardware: set[int] = set()\n    scraps: set[int] = set()\n    for group in _components(leaf.data):\n        points = [leaf.data.vertices[i].co for i in group]\n        lo = [min(p[k] for p in points) for k in range(3)]\n        hi = [max(p[k] for p in points) for k in range(3)]\n        # Disconnected casing end caps also intersect the leaf's fitted plane.\n        if hi[0] < width * 0.15 and (hi[2] < 0.025 or lo[2] > height - 0.005):\n            scraps.update(group)\n        is_handle = lo[0] > width * 0.75 and lo[2] > height * 0.46 and hi[2] < height * 0.57\n        is_hinge = hi[0] < width * 0.10 and hi[2] - lo[2] < height * 0.04 and lo[2] > 0.1\n        if is_handle or is_hinge:\n            hardware.update(group)\n    for poly in leaf.data.polygons:\n        if not all(i in hardware for i in poly.vertices):\n            poly.material_index = paint_index\n    if scraps:\n        bm = bmesh.new()\n        bm.from_mesh(leaf.data)\n        bm.verts.ensure_lookup_table()\n        bmesh.ops.delete(bm, geom=[bm.verts[i] for i in scraps], context='VERTS')\n        bm.to_mesh(leaf.data)\n        bm.free()\n    leaf.data.update()\n\n\ndef fit_leaf_to_collision(leaf, width, height, thickness, bottom):\n    \"\"\"Fit the painted timber, excluding hardware, to the hinge collision slab.\n\n    The imported casing fragments previously biased the fit, leaving 75 mm\n    of empty space at the hinge and a small yaw error. The large timber faces\n    provide the actual panel axis and bounds. The hinge is on the front edge:\n    local timber spans x=[0,width], y=[-thickness,0].\n    \"\"\"\n    panel = max(leaf.data.polygons, key=lambda p: p.area)\n    normal = panel.normal.copy()\n    if normal.y < 0:\n        normal.negate()\n    yaw = math.atan2(-normal.x, normal.y)\n    leaf.data.transform(Matrix.Rotation(-yaw, 4, 'Z'))\n    leaf.data.update()\n    body_ids = {i for p in leaf.data.polygons if p.area > 0.005 for i in p.vertices}\n    points = [leaf.data.vertices[i].co for i in body_ids]\n    lo = Vector(tuple(min(p[k] for p in points) for k in range(3)))\n    hi = Vector(tuple(max(p[k] for p in points) for k in range(3)))\n    scale = Vector((width / (hi.x - lo.x), thickness / (hi.y - lo.y), height / (hi.z - lo.z)))\n    transform = (Matrix.Translation((0, -thickness, bottom))\n                 @ Matrix.Diagonal((*scale, 1)) @ Matrix.Translation(-lo))\n    leaf.data.transform(transform)\n    leaf.data.update()\n    return {'corrected_panel_yaw_deg': math.degrees(yaw),\n            'body_bounds_local': [[0, width], [-thickness, 0], [bottom, bottom + height]]}\n\n\ndef _fitted_frame(spec, aperture, wall, floor_z, paint):\n    \"\"\"Thin architrave on the plaster plane, independently of the reveal depth.\n\n    The opening is measured in world X, while the trim is measured along the\n    splayed wall. Projecting its width avoids exposing the carved aperture.\n    \"\"\"\n    lo, hi = aperture\n    yaw = math.radians(float(wall['yaw_deg'])) if wall else 0.0\n    normal = Vector(wall['normal']) if wall else Vector((0, 1, 0))\n    centre_x = (lo.x + hi.x) * 0.5\n    front_y = ((wall['offset'] - normal.x * centre_x) / normal.y\n               if wall else float(spec.get('frame_front_y_m', hi.y)))\n    origin = Vector((centre_x, front_y, floor_z))\n    rotation = Matrix.Rotation(yaw, 4, 'Z')\n    half = (hi.x - lo.x) / (2.0 * math.cos(yaw))\n    height = hi.z - floor_z\n    trim = float(spec.get('frame_trim_width_m', 0.065))\n    proud = float(spec.get('frame_front_proud_m', 0.018))\n    parts = []\n\n    def board(name, x0, x1, z0, z1, y0, y1):\n        bpy.ops.mesh.primitive_cube_add(size=1)\n        obj = bpy.context.object\n        obj.name = name\n        obj.dimensions = (x1 - x0, y1 - y0, z1 - z0)\n        bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)\n        obj.location = origin + rotation @ Vector(((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2))\n        obj.rotation_euler.z = yaw\n        obj.data.materials.append(paint)\n        bevel = obj.modifiers.new('Soft painted edges', 'BEVEL')\n        bevel.width = 0.0015\n        bevel.segments = 3\n        obj.modifiers.new('Corner normals', 'WEIGHTED_NORMAL')\n        parts.append(obj)\n\n    # Optional surface architrave; the recessed liners also work on their own.\n    architrave = bool(spec.get('frame_architrave', True))\n    if architrave:\n        for side, a, b in [('left', -half - trim, -half), ('right', half, half + trim)]:\n            board(f'door_frame_{side}', a, b, 0, height, -0.006, proud)\n            bead_a = b - 0.009 if side == 'left' else a\n            board(f'door_frame_{side}_bead', bead_a, bead_a + 0.009, 0, height, proud - 0.002, proud + 0.004)\n        board('door_frame_head', -half - trim, half + trim, height, height + trim, -0.006, proud)\n        board('door_frame_head_bead', -half, half, height, height + 0.009, proud - 0.002, proud + 0.004)\n    # The reveal is a shallow liner behind the trim, never a scaled display box.\n    depth = float(spec.get('frame_reveal_depth_m', 0.075))\n    if not architrave:\n        paint = paint.copy()\n        paint.name = 'door_reveal_plaster'\n        bsdf = paint.node_tree.nodes.get('Principled BSDF')\n        bsdf.inputs['Base Color'].default_value = (*spec.get('reveal_color', [0.52, 0.50, 0.46]), 1.0)\n        bsdf.inputs['Roughness'].default_value = 0.78\n    liner_front = 0.001 if architrave else -0.004\n    for side, a, b in [('left', -half - 0.018, -half), ('right', half, half + 0.018)]:\n        board(f'door_frame_{side}_liner', a, b, 0, height, -depth, liner_front)\n    board('door_frame_head_liner', -half, half, height, height + 0.018, -depth, liner_front)\n    return parts[0], {'construction': 'fitted_trim', 'opening_width_m': round(half * 2, 4),\n                      'opening_height_m': round(height, 4), 'architrave_width_m': trim,\n                      'front_proud_m': proud if architrave else 0.0, 'reveal_depth_m': depth,\n                      'architrave_enabled': architrave,\n                      'yaw_deg': round(math.degrees(yaw), 3)}\n\n\ndef strip_room_casing(\n    room: Iterable[bpy.types.Object],\n    *,\n    box_lo: Vector,\n    box_hi: Vector,\n) -> int:\n    \"\"\"Delete the room asset's own door casing, so the new frame can own the opening.\n\n    ``cloe_room.glb`` builds its doorway as a casing **box**: two architrave\n    faces, a 0.56 m reveal and a stop, all standing proud of the wall on the\n    splayed panel the door is cut into. Dropping the door asset's frame inside\n    that leaves one casing hiding the other -- measured, the room's stands\n    1.8 cm proud, so a frame set flush to the plaster is completely invisible\n    and one set in front of it reads as a second architrave.\n\n    So the room's casing goes. It is identified component by component -- a\n    connected island whose every vertex falls inside the doorway's own box --\n    which keeps the window, which shares the same ``do&win`` mesh, and every\n    wall panel, whose faces run far past that box, untouched.\n    \"\"\"\n    total = 0\n    for obj in room:\n        if obj.type != 'MESH':\n            continue\n        matrix = obj.matrix_world\n        doomed: set[int] = set()\n        for group in _components(obj.data):\n            points = [matrix @ obj.data.vertices[i].co for i in group]\n            if all(\n                box_lo[k] - 1e-4 <= point[k] <= box_hi[k] + 1e-4\n                for point in points\n                for k in range(3)\n            ):\n                doomed.update(group)\n        if not doomed:\n            continue\n        bm = bmesh.new()\n        bm.from_mesh(obj.data)\n        bm.verts.ensure_lookup_table()\n        bmesh.ops.delete(bm, geom=[v for v in bm.verts if v.index in doomed], context='VERTS')\n        bm.to_mesh(obj.data)\n        bm.free()\n        obj.data.update()\n        total += len(doomed)\n        print(f'[door] removed {len(doomed)} casing verts from {obj.name}')\n    print(f'[door] room casing stripped: {total} verts')\n    return total\n\n\ndef build_door_from_asset(\n    path,\n    spec: dict[str, Any],\n    *,\n    leaf_width_m: float,\n    leaf_height_m: float,\n    hinge_world: Vector,\n    floor_z: float,\n    aperture: tuple[Vector, Vector],\n    wall: dict[str, Any] | None = None,\n) -> tuple[bpy.types.Object | None, bpy.types.Object | None, dict[str, Any]]:\n    \"\"\"Import the door asset and return its leaf and frame as scene objects.\"\"\"\n    previous = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(path))\n    bpy.context.view_layer.update()\n    imported = [o for o in bpy.data.objects if o not in previous]\n    for obj in imported:\n        obj.animation_data_clear()\n    _tame_materials(\n        imported,\n        float(spec.get('emission_scale', 0.0)),\n        float(spec.get('roughness_min', 0.35)),\n    )\n\n    meshes = [o for o in imported if o.type == 'MESH']\n    if len(meshes) != 1:\n        raise RuntimeError(f'{path} has {len(meshes)} meshes; this loader expects one')\n    source = meshes[0]\n    # glTF wraps the mesh in empties that carry the exporter's unit scaling and\n    # the Y-up -> Z-up correction. Everything below is written in the asset's\n    # own world space, so bake that chain into the mesh and cut the parent: left\n    # in place the hinge translation lands in local space and the leaf ends up\n    # 2 m below the floor.\n    world = source.matrix_world.copy()\n    source.parent = None\n    source.data.transform(world)\n    source.matrix_world = Matrix.Identity(4)\n    bpy.context.view_layer.update()\n\n    leaf_ids, frame_ids, measurement = _split(source)\n    print(\n        f'[door] asset {path.name}: leaf {len(leaf_ids)} verts of {len(source.data.vertices)}, '\n        f'frame {len(frame_ids)}, artist left it {math.degrees(measurement[\"angle_rad\"]):.2f} deg open, '\n        f'leaf {measurement[\"width_units\"]:.2f} x {measurement[\"height_units\"]:.2f} units '\n        f'({measurement[\"thickness_units\"]:.2f} thick), hinge at '\n        f'({measurement[\"hinge_units\"].x:.2f}, {measurement[\"hinge_units\"].y:.2f})'\n    )\n\n    leaf = _carve(source, leaf_ids, 'door_leaf')\n    leaf.data.name = 'door_leaf'\n    for slot in source.material_slots:\n        if slot.material is not None and slot.material.name not in leaf.data.materials:\n            leaf.data.materials.append(slot.material)\n\n    leaf_info = _repose_leaf(\n        leaf,\n        measurement,\n        width_m=leaf_width_m,\n        height_m=leaf_height_m,\n    )\n    print(\n        f'[door] leaf -> x{leaf_info[\"leaf_x_m\"]} y{leaf_info[\"leaf_y_m\"]} z{leaf_info[\"leaf_z_m\"]} '\n        f'(scale {leaf_info[\"scale_x\"]:.5f} x {leaf_info[\"scale_z\"]:.5f})'\n    )\n\n    frame = None\n    frame_info: dict[str, Any] = {}\n    fitted = spec.get('frame_style') == 'fitted'\n    paint = _paint_material(spec) if fitted else None\n    if fitted:\n        _refinish_leaf(leaf, paint, leaf_height_m, leaf_width_m)\n    keep_frame = bool(spec.get('frame_enabled', True))\n    if keep_frame and fitted:\n        frame, frame_info = _fitted_frame(spec, aperture, wall, floor_z, paint)\n        print(f'[door] fitted frame: {frame_info}')\n    elif keep_frame and frame_ids:\n        frame = _carve(source, frame_ids, 'door_frame')\n        frame.data.name = 'door_frame'\n        for slot in source.material_slots:\n            if slot.material is not None and slot.material.name not in frame.data.materials:\n                frame.data.materials.append(slot.material)\n        opening = _frame_opening(frame)\n        frame_info = _place_frame(\n            frame,\n            opening,\n            measurement,\n            spec,\n            leaf_width_m=leaf_width_m,\n            aperture=aperture,\n            wall=wall,\n            floor_z=floor_z,\n        )\n        print(\n            f'[door] frame -> x{frame_info[\"outer_x_m\"]} y{frame_info[\"outer_y_m\"]} '\n            f'z{frame_info[\"outer_z_m\"]}, opening {frame_info[\"opening_width_m\"]:.3f} x '\n            f'{frame_info[\"opening_height_m\"]:.3f} m, architrave {frame_info[\"architrave_width_m\"]:.3f} m '\n            f'side / {frame_info[\"architrave_head_m\"]:.3f} m head, yaw {frame_info[\"yaw_deg\"]:+.2f} deg, '\n            f'sunk {frame_info[\"sunk_below_floor_m\"]:.3f} m'\n        )\n\n    for obj in imported:\n        if obj is not leaf and obj is not frame and obj.name in bpy.data.objects:\n            bpy.data.objects.remove(obj, do_unlink=True)\n    bpy.context.view_layer.update()\n    return leaf, frame, {'leaf': leaf_info, 'frame': frame_info}\n", "home_basketball_door.scenario_io": "\"\"\"Shared scenario loading for the home_basketball_door scene.\n\n``scenario.json`` holds three blocks -- ``assets``, ``physics`` and\n``layout`` -- and every entry point (simulator, renderer, PCVE builder) reads\nit through here, so a case's override file is merged exactly one way: group by\ngroup, key by key, with nested dicts merged recursively and everything else\nreplaced wholesale.\n\nAn override file is therefore the same shape as ``scenario.json`` with only the\nkeys that differ, e.g. ``{\"physics\": {\"lid_mass\": 0.9}}``. That is also the\nshape ``build_pcve_home_basketball_door.py`` writes for each edit case.\n\"\"\"\n\nfrom __future__ import annotations\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport copy\nimport json\nfrom pathlib import Path\nfrom typing import Any\n\nSCENE_DIR = _PCVE_ROOT / 'assets' / 'scenarios' / 'home_basketball_door'\nSCENARIO_PATH = SCENE_DIR / 'scenario.json'\n\nGROUPS = ('assets', 'physics', 'layout')\n\n\ndef read_json(path: Path) -> dict[str, Any]:\n    data = json.loads(Path(path).expanduser().read_text(encoding='utf-8'))\n    if not isinstance(data, dict):\n        raise ValueError(f'Expected a JSON object: {path}')\n    return data\n\n\ndef merge(base: dict[str, Any], updates: dict[str, Any]) -> dict[str, Any]:\n    merged = copy.deepcopy(base)\n    for key, value in updates.items():\n        if isinstance(value, dict) and isinstance(merged.get(key), dict):\n            merged[key] = merge(merged[key], value)\n        else:\n            merged[key] = copy.deepcopy(value)\n    return merged\n\n\ndef load_scenario(\n    scenario_path: Path | None = None,\n    overrides_path: Path | None = None,\n) -> dict[str, Any]:\n    \"\"\"Baseline scenario, with an optional overrides file merged on top.\"\"\"\n    scenario = read_json(scenario_path or SCENARIO_PATH)\n    for group in GROUPS:\n        scenario.setdefault(group, {})\n    if overrides_path is not None:\n        scenario = merge(scenario, read_json(overrides_path))\n        scenario['overrides_path'] = str(Path(overrides_path).expanduser().resolve())\n    return scenario\n\n\ndef write_json(path: Path, payload: Any) -> None:\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding='utf-8')\n", "home_basketball_door": "\"\"\"Shared support modules for home_basketball_door.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n"}""")

_BUNDLE_SCENE_ALIAS = 'home_basketball_door'
_BUNDLE_ALIASES = ['door_asset', 'scenario_io', 'home_basketball_door', 'home_basketball_door.door_asset', 'home_basketball_door.scenario_io']

class _SceneBundleLoader(_bundle_abc.MetaPathFinder, _bundle_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        package = (fullname == "scene_support" or fullname.count(".") == 1 and fullname.startswith("scene_support.") or fullname == _BUNDLE_SCENE_ALIAS)
        return _bundle_util.spec_from_loader(fullname, self, is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        package = module.__spec__.submodule_search_locations is not None
        if name == "scene_support":
            origin = _BUNDLE_SCENE / "scene_support" / "__init__.py"
        elif name == _BUNDLE_SCENE_ALIAS:
            origin = _BUNDLE_SCENE / "scene_support" / name / "__init__.py"
        elif name.startswith(_BUNDLE_SCENE_ALIAS + "."):
            origin = _BUNDLE_SCENE / "scene_support" / name.replace(".", "/")
            origin = origin.with_suffix(".py")
        elif name.startswith("scene_support."):
            tail = name.split(".", 1)[1]
            if package:
                origin = _BUNDLE_SCENE / "scene_support" / tail / "__init__.py"
            else:
                origin = _BUNDLE_SCENE / "scene_support" / tail.replace(".", "/")
                origin = origin.with_suffix(".py")
        else:
            origin = _BUNDLE_SCRIPTS / (name + ".py")
        module.__file__ = str(origin)
        module.__package__ = name if package else (_BUNDLE_SCENE_ALIAS if name.startswith(_BUNDLE_SCENE_ALIAS + ".") or name in ['door_asset', 'scenario_io'] else name.rpartition("." )[0])
        if package:
            module.__path__ = [str(_BUNDLE_SCENE)] if name == _BUNDLE_SCENE_ALIAS else []
        source = _BUNDLE_SOURCES[name]
        exec(compile(source, str(origin), "exec"), module.__dict__)

def install_scene_support():
    if not any(isinstance(item, _SceneBundleLoader) for item in _bundle_sys.meta_path):
        _bundle_sys.meta_path.insert(0, _SceneBundleLoader())

install_scene_support()




